globalThis.KNOWLEDGE_DATA={"version":1,"title":"运动训练学 · 第四章第二、三节知识树","sections":["tr4s2","tr4s3"],"nodes":[{"id":"training-book","parentId":null,"kind":"book","original":true,"title":"运动训练学（第二版）","printedPages":[141,164],"body":["田麦久主编，高等教育出版社，2017年第二版。样板仅覆盖第四章第二、三节。"],"keywords":[]},{"id":"training-ch4","parentId":"training-book","kind":"chapter","original":true,"title":"第四章 运动员竞技能力及其训练（下）","printedPages":[127],"body":["本样板保留第四章作为上级归属，展开第二节与第三节。"],"keywords":[]},{"id":"tr4s2","parentId":"training-ch4","kind":"section","original":true,"title":"第二节 运动员心理能力及其训练","printedPages":[141,142,143,144,145,146,147,148,149,150,151,152,153,154],"body":["本节依次讨论运动员心理能力的定义及其构成、常用的心理训练方法、心理训练的基本要求。先分清分类依据，再把不同心理技能与训练、比赛情境联系起来。"],"keywords":["定义及其构成","心理训练方法","基本要求"]},{"id":"tr4s3","parentId":"training-ch4","kind":"section","original":true,"title":"第三节 运动员知识能力及其训练","printedPages":[154,155,156,157,158,159,160,161,162,163,164],"body":["本节按“是什么与怎样构成—怎样获得和提高—怎样运用”展开。学习时要分别辨清知识的分类标准，并理解实践经验、理论表达与再次运用之间的联系。"],"keywords":["构成","获得和提高","运用"]},{"id":"psy-ability","parentId":"tr4s2","title":"一、运动员心理能力的定义及其构成","kind":"heading","original":true,"printedPages":[141,142,143],"body":["本部分先解释心理能力是什么，再从训练目的与训练阶段两个不同角度认识心理训练，最后列出影响心理能力的八类因素。","心理能力服务于运动行为的组织与控制，既涉及相对稳定的个性心理特征，也涉及随训练和竞赛情境变化的心理过程。"],"keywords":["个性心理特征","心理过程","训练分类","影响因素"],"explanation":"","core":"后续各种心理训练方法的共同起点：明确要改善什么，再选择相应手段。"},{"id":"psy-overview","parentId":"psy-ability","title":"（一）运动员心理能力概述","kind":"heading","original":true,"printedPages":[141,142,143],"body":["从含义、可训练性、训练内容和训练阶段四个角度理解心理能力。心理训练应像体能、技术、战术训练一样有意识地开展。"],"keywords":["含义","可训练性","系统训练"],"explanation":""},{"id":"psy-definition","parentId":"psy-overview","title":"1. 心理能力释义","kind":"heading","original":true,"printedPages":[141],"body":["运动员心理能力即指运动员与训练竞赛有关的个性心理特征，以及依训练竞赛的需要把握和调整心理过程的能力，是运动员竞技能力的重要组成部分。","其本质在于运动员对自己运动行为的把握与控制，包括训练及竞赛行为的动员能力、控制能力、意志能力等。心理活动与脑的活动有依存关系，不能按日常“心想”等用语把它理解为心脏活动。"],"keywords":["个性心理特征","把握和调整心理过程","竞技能力","动员","控制","意志"],"explanation":"“有信心、能坚持”只是其中一部分；能按比赛需要调动自己、稳定情绪、调整注意，也属于心理能力。","core":"定义有两部分：相对稳定的心理特征＋按情境调整心理过程的能力，答题时两者都要覆盖。","definition":"运动员心理能力即指运动员与训练竞赛有关的个性心理特征，以及依训练竞赛的需要把握和调整心理过程的能力，是运动员竞技能力的重要组成部分。"},{"id":"psy-training","parentId":"psy-overview","title":"2. 运动员心理训练的内容与特点","kind":"heading","original":true,"printedPages":[141,142,143],"body":["超常心理素质和高水平心理技能需要通过经验、系统训练及个人努力形成；心理训练的主要目的和任务是发展心理能力，为训练和比赛做好心理准备。","理解心理训练时要分清两套分类：一套按训练内容和针对性，分为基础的与有针对性的心理训练；另一套依据与训练和比赛的关系，分为日常与比赛期心理训练。两套分类不能简单一一等同。"],"keywords":["系统训练","心理准备","两套分类"],"explanation":"“练什么、针对什么”和“什么时候练”是两个问题，因而会有两套分类。","core":"本节最容易混淆的层级：基础/专门是内容与针对性；日常/赛期是与训练比赛的关系。","definition":"心理训练是以发展运动员的心理能力，为训练和比赛做好心理准备作为其主要目的和任务的。"},{"id":"psy-content-class","parentId":"psy-training","title":"按训练内容与针对性：基础的心理训练与有针对性的心理训练","kind":"point","original":false,"printedPages":[142],"body":["两类训练共同构成系统心理训练：基础训练建立参与训练竞赛所必需的基本素质和技能，有针对性的训练解决具体比赛准备或具体心理问题。"],"keywords":["基础心理训练","一般心理训练","有针对性的心理训练","专门心理训练"],"explanation":""},{"id":"psy-basic","parentId":"psy-content-class","title":"基础的心理训练","kind":"point","original":true,"printedPages":[142],"body":["亦称一般心理训练，发展训练和比赛所需的基本心理素质，包含掌握各种心理技能、发展专项心理素质、培养良好个性品质三方面。"],"keywords":["基本心理素质","心理技能","专项心理素质","个性品质"],"explanation":"“一般”不表示没有专项内容；图中“发展专项心理素质”正属于基础训练。"},{"id":"psy-basic-skills","parentId":"psy-basic","title":"掌握各种心理技能","kind":"point","original":true,"printedPages":[142],"body":["包括目标设置技能、想象技能、放松技能、注意集中技能等。它们是运动员能主动掌握并反复使用的调控工具。"],"keywords":["目标设置","想象","放松","注意集中"],"explanation":""},{"id":"psy-basic-special","parentId":"psy-basic","title":"发展专项心理素质","kind":"point","original":true,"printedPages":[142],"body":["包括球感、水感等专门化知觉以及专项意识。发展内容应与项目的运动环境、动作特点和判断要求相适应。"],"keywords":["专门化知觉","球感","水感","专项意识"],"explanation":""},{"id":"psy-basic-personality","parentId":"psy-basic","title":"培养良好个性品质","kind":"point","original":true,"printedPages":[142],"body":["包括强烈的成就动机、坚定的自信心和顽强的意志品质。它们为长期投入训练和应对竞赛困难提供支持。"],"keywords":["成就动机","自信心","意志品质"],"explanation":""},{"id":"psy-targeted","parentId":"psy-content-class","title":"有针对性的心理训练","kind":"point","original":true,"printedPages":[142],"body":["亦称专门心理训练，旨在为某个具体比赛做好心理准备，同时包括针对某些心理障碍开展的训练。图示分为消除某些心理障碍、做好赛前心理准备两个分支。"],"keywords":["专门心理训练","具体比赛","心理障碍","赛前准备"],"explanation":""},{"id":"psy-targeted-obstacle","parentId":"psy-targeted","title":"消除某些心理障碍","kind":"point","original":true,"printedPages":[142],"body":["图示举出系统脱敏训练、行为强化等方法，说明专门训练可以围绕明确心理问题选择相应手段。此处作为教材体系说明，不将这些方法展开为自行诊断或治疗流程。"],"keywords":["系统脱敏训练","行为强化"],"explanation":""},{"id":"psy-targeted-preparation","parentId":"psy-targeted","title":"做好赛前心理准备","kind":"point","original":true,"printedPages":[142],"body":["图示举出模拟训练、心理动员等方法，目的是让运动员在具体比赛条件下形成较合适的心理状态。"],"keywords":["模拟训练","心理动员"],"explanation":""},{"id":"psy-period-class","parentId":"psy-training","title":"按与训练和比赛的关系：比赛期心理训练与日常心理训练","kind":"point","original":false,"printedPages":[142,143],"body":["比赛期训练主要调整心理过程，日常训练相对偏重发展心理技能、改善个性心理特征；二者分工有侧重，而非彼此割裂。"],"keywords":["比赛期","日常","心理过程","个性心理特征"],"explanation":""},{"id":"psy-competition","parentId":"psy-period-class","title":"赛期心理训练","kind":"point","original":false,"printedPages":[142],"body":["依据特定比赛需要进行，包含赛前的心理准备、赛中的心理控制和赛后的心理调整。不能将“赛期”缩小为仅仅赛前动员。"],"keywords":["赛前准备","赛中控制","赛后调整"],"explanation":""},{"id":"psy-before","parentId":"psy-competition","title":"赛前：心理准备","kind":"point","original":false,"printedPages":[142],"body":["激发比赛动机，控制适宜的激活水平，增强参赛信心，建立稳定而灵活的参赛思维程序和行为程序。赛前体能、技能与战术能力相对稳定，但心理状态仍可能明显波动，因此应重视心理准备。"],"keywords":["动机","激活水平","信心","思维程序","行为程序"],"explanation":""},{"id":"psy-during","parentId":"psy-competition","title":"赛中：心理控制","kind":"point","original":false,"printedPages":[142],"body":["面对环境与比赛进程变化，保持良好而稳定的情绪，以便充分发挥体能、技能和战术水平；比赛本身也是心理能力的高强度锻炼。"],"keywords":["情绪稳定","变化情境","能力发挥"],"explanation":""},{"id":"psy-after","parentId":"psy-competition","title":"赛后：心理调整","kind":"point","original":false,"printedPages":[142],"body":["对成功者肯定积极情绪体验，同时反思胜利掩盖的问题，防止自满和松懈；对失败者缓解消极体验，寻找局部积极表现，恢复再战求胜的动机。"],"keywords":["成功者","失败者","积极体验","自满松懈","再战动机"],"explanation":""},{"id":"psy-daily","parentId":"psy-period-class","title":"日常心理训练（训练期心理训练）","kind":"point","original":false,"printedPages":[142,143],"body":["日常训练偏重发展心理技能和改善个性心理特征。依据年龄、训练年限和训练阶段安排一般与专项心理训练比例：基础阶段少年选手侧重一般特征，随专项任务加重逐步增加符合专项特点的心理训练。"],"keywords":["年龄","训练年限","训练阶段","一般与专项比例"],"explanation":""},{"id":"psy-factors","parentId":"psy-ability","title":"（二）运动员心理能力的影响因素","kind":"heading","original":true,"printedPages":[143],"body":["影响心理能力的因素包括个性特征、竞赛情绪、注意特征、感知觉能力、比赛动机水平、意志品质、自信水平和中枢神经疲劳。分析具体运动员时，应结合多方面表现，不能把所有失常都归为缺乏意志或不够自信。"],"keywords":["个性","情绪","注意","感知觉","动机","意志","自信","疲劳"],"explanation":"","core":"八项因素是分析心理状态和选择训练内容的检查表，彼此可能相互影响。"},{"id":"psy-factor-personality","parentId":"psy-factors","title":"（1）个性特征。","kind":"point","original":true,"printedPages":[143],"body":["测试指标包括性格倾向性、精神质（适应力）和情绪稳定性。"],"keywords":["性格倾向性","精神质（适应力）","情绪稳定性"],"explanation":""},{"id":"psy-factor-emotion","parentId":"psy-factors","title":"（2）竞赛情绪。","kind":"point","original":true,"printedPages":[143],"body":["包括赛前情绪和竞赛状态焦虑水平。"],"keywords":["赛前情绪","竞赛状态焦虑"],"explanation":""},{"id":"psy-factor-attention","parentId":"psy-factors","title":"（3）注意特征。","kind":"point","original":true,"printedPages":[143],"body":["包括注意的分配、广度、稳定性和转移。"],"keywords":["分配","广度","稳定性","转移"],"explanation":""},{"id":"psy-factor-perception","parentId":"psy-factors","title":"（4）感知觉能力。","kind":"point","original":true,"printedPages":[143],"body":["包括速度知觉和反应能力。"],"keywords":["速度知觉","反应能力"],"explanation":""},{"id":"psy-factor-motivation","parentId":"psy-factors","title":"（5）比赛动机水平。","kind":"point","original":true,"printedPages":[143],"body":["包括赛前动机水平和动机变化趋势。"],"keywords":["赛前动机","变化趋势"],"explanation":""},{"id":"psy-factor-will","parentId":"psy-factors","title":"（6）意志品质。","kind":"point","original":true,"printedPages":[143],"body":["包括主动性、果断性、坚韧性、自制性和自觉性。"],"keywords":["主动性","果断性","坚韧性","自制性","自觉性"],"explanation":""},{"id":"psy-factor-confidence","parentId":"psy-factors","title":"（7）自信水平。","kind":"point","original":true,"printedPages":[143],"body":["包括一般自信、特质自信和状态自信。"],"keywords":["一般自信","特质自信","状态自信"],"explanation":""},{"id":"psy-factor-fatigue","parentId":"psy-factors","title":"（8）中枢神经疲劳。","kind":"point","original":true,"printedPages":[143],"body":["主要通过运动员自我感受的测试予以判定。"],"keywords":["自我感受","疲劳"],"explanation":""},{"id":"psy-methods","parentId":"tr4s2","title":"二、常用的心理训练方法","kind":"heading","original":true,"printedPages":[143,144,145,146,147,148,149,150,151,152],"body":["本部分依次介绍目标设置、想象、放松、注意和意志品质训练。应根据心理任务选择并组合方法，而不是把五种方法看作互相替代的同一种训练。"],"keywords":["目标设置","想象","放松","注意","意志品质"],"explanation":"","core":"方法需要回答“改善什么、怎样练、什么条件下用”，避免只背方法名称。"},{"id":"psy-goals","parentId":"psy-methods","title":"（一）目标设置技能","kind":"heading","original":true,"printedPages":[143,144,145],"body":["目标设置及为实现目标制定的系统计划，有助于增强自信和提高竞技能力。科学目标能让注意与行为指向训练任务，动员能量和努力，在进步缓慢时维持坚持，并促使教练员和运动员寻找合适策略。","设置目标需要同时考虑表现与结果、难度、现实性、具体性、时间跨度、个体与全队六个方面。这是六组考量，不是互斥的六类目标：同一个目标可以同时具体、现实、有挑战性、短期而且属于个体。"],"keywords":["指向任务","动员努力","坚持","寻找策略","六组考量"],"explanation":"“本月把某个动作的达标率提高到约定水平”可以同时满足多条原则；六个方面要一起检查。","core":"目标不是喊口号，而是用可控制、可检查的要求引导训练行为。"},{"id":"psy-goal-performance","parentId":"psy-goals","title":"1. 表现的目标与结果的目标","kind":"heading","original":true,"printedPages":[143,144],"body":["应把重点放在运动员能够控制的竞赛表现上，而不是仅以战胜他人、名次或输赢定义成功。评价应重视是否完成自身表现要求和付出相应努力；这不等于否认比赛结果，而是把行动控制点放回自身。"],"keywords":["自身控制","表现目标","结果目标"],"explanation":"“完成自己的技术要求”主要取决于自身；“必须夺冠”还受对手和比赛条件影响。"},{"id":"psy-goal-challenge","parentId":"psy-goals","title":"2. 挑战性的目标与轻而易举的目标","kind":"heading","original":true,"printedPages":[144],"body":["目标应有挑战性，以激发努力和动机；但难度不能高到反复努力仍无法达到或使运动员直接放弃。根据能力与进步逐步提高要求，在达成后获得成功体验，支持下一阶段努力。"],"keywords":["挑战性","适度难度","动机","逐步提高"],"explanation":"有挑战不等于越难越好，要能通过努力接近和实现。"},{"id":"psy-goal-realistic","parentId":"psy-goals","title":"3. 现实的目标与非现实的目标","kind":"heading","original":true,"printedPages":[144],"body":["以真实水平为起点，区分“现在具备的水平”和“希望具有的水平”。教练员与运动员应建立信任，根据实际进程适当调整目标，共同服务长远发展，避免仅因渴望取胜而脱离实际。"],"keywords":["真实水平","相互信任","适当调整"],"explanation":"现实性检查的是是否有实际依据；它与挑战性并不矛盾。"},{"id":"psy-goal-specific","parentId":"psy-goals","title":"4. 具体的目标与笼统的目标","kind":"heading","original":true,"printedPages":[144],"body":["目标应明确成功标准，尽可能数量化，并限定特定时间或事件，以便指导和评价行动。“尽最大努力”可以表达追求，却因缺乏清楚界限而不足以充当具体训练目标。"],"keywords":["成功标准","数量化","时间或事件","可检查"],"explanation":"把“好好练”改成可以观察、记录和核对的任务。"},{"id":"psy-goal-time","parentId":"psy-goals","title":"5. 短期的目标与长期的目标","kind":"heading","original":true,"printedPages":[144,145],"body":["通过一系列短期目标推进长期方向。短期目标便于及时指导、反馈、奖励成功、发现技能缺口和调整训练；长期目标明确发展方向，并把单次比赛置于整体过程之中，减轻对一次结果的过度紧张。原书提醒明确的近期执行目标不宜跨度过大，并以一个月作说明；学习时应理解为近期细化、远期滚动调整，不能否认长期规划的价值。"],"keywords":["短期推进","长期方向","及时反馈","调整训练","缓解应激"],"explanation":"短期回答“眼下具体做什么”，长期回答“这些努力最终往哪里去”。"},{"id":"psy-goal-individual","parentId":"psy-goals","title":"6. 个体的目标与全队的目标","kind":"heading","original":true,"printedPages":[145],"body":["目标计划应落实个体目标，明确每位运动员可控制的责任。集体项目需要全队目标来引导合作，但只有与清楚的个体任务相结合才有效；应注意并预防个体与全队目标冲突。"],"keywords":["个体责任","全队合作","结合","预防冲突"],"explanation":"团队说“提高防守”，还需落实到每人的站位、协防和执行责任。"},{"id":"psy-imagery","parentId":"psy-methods","title":"（二）想象技能","kind":"heading","original":true,"printedPages":[145,146,147],"body":["想象技能是指运动员利用头脑中已形成的运动表象进行训练的一种技能。","其作用包括获得和练习复杂动作技能、演练特殊比赛技术与战术、获得其他心理技能。想象训练亦称念动训练或意念训练，应围绕准确而可控制的运动表象进行，不能仅理解为幻想取胜。"],"keywords":["运动表象","复杂动作","技术战术","心理技能","念动训练","意念训练"],"explanation":"例如在头脑中按真实节奏演练助跑、起跳和过杆，并调动视觉、动觉等体验。它辅助实际训练，不能用愿望代替动作练习。","core":"“有感觉、形象清楚、能够控制”是想象训练质量的关键。","definition":"想象技能是指运动员利用头脑中已形成的运动表象进行训练的一种技能。"},{"id":"psy-imagery-stages","parentId":"psy-imagery","title":"1. 发展想象技能的三个阶段","kind":"heading","original":true,"printedPages":[146],"body":["发展顺序为感觉意识、鲜明生动性、控制性：先有清楚的动作体验，再使形象鲜明，最后使想象过程按任务需要进行。"],"keywords":["感觉意识","鲜明生动性","控制性"],"explanation":"三个阶段是发展顺序，不是三种放松方法。"},{"id":"psy-imagery-stage-sense","parentId":"psy-imagery-stages","title":"第一阶段：感觉意识。","kind":"point","original":true,"printedPages":[146],"body":["以已经获得的运动经验为基础，清楚意识到完成动作时的身体位置、脚步、时间节律、动作连贯性、方向变化，以及视觉、动觉、听觉等体验。"],"keywords":["运动经验","动作感觉","视觉","动觉","听觉"],"explanation":"先知道真实动作“是什么感觉”，头脑中的演练才有依据。"},{"id":"psy-imagery-stage-vivid","parentId":"psy-imagery-stages","title":"第二阶段：鲜明生动性。","kind":"point","original":true,"printedPages":[146],"body":["让各种感觉形成鲜明生动的形象。基础薄弱时可从熟悉场景开始，再逐步变换并与运动项目联系，鼓励运动员自己设计练习、主动参与训练。"],"keywords":["多感觉","鲜明生动","由简到难","主动设计"],"explanation":"不是只看一张模糊图片，而是让动作或情境像实际体验一样清楚。"},{"id":"psy-imagery-stage-control","parentId":"psy-imagery-stages","title":"第三阶段：控制性。","kind":"point","original":true,"printedPages":[146],"body":["练习按需要操纵想象形象，使其产生所需结果。可以先做简单的身体感觉想象，再进入项目专门练习，例如在头脑中运球、练习投篮或演练防守。"],"keywords":["操纵形象","所需结果","专项练习"],"explanation":"形象很清楚却总不受控制地出现失误，说明仍需练习控制性。"},{"id":"psy-imagery-conditions","parentId":"psy-imagery","title":"2. 想象训练的准备条件","kind":"heading","original":true,"printedPages":[146,147],"body":["准备条件包括背景、注意放松状态和想象提示物。安排条件应随技能发展由容易逐步过渡到复杂竞赛情境。"],"keywords":["背景","注意放松状态","想象提示物"],"explanation":""},{"id":"psy-imagery-background","parentId":"psy-imagery-conditions","title":"（1）背景。","kind":"point","original":true,"printedPages":[146],"body":["初学者宜从没有分心因素的环境开始，熟练后逐步在多种甚至激烈竞赛背景下练习，在集中于内部形象时学会过滤外部干扰。"],"keywords":["初学安静","熟练复杂","过滤干扰"],"explanation":"不能把“安静环境适合开始”记成“只有绝对安静才能想象”。"},{"id":"psy-imagery-relaxed","parentId":"psy-imagery-conditions","title":"（2）注意放松的状态。","kind":"point","original":true,"printedPages":[146,147],"body":["每次练习前使身心平静、肌肉放松，同时仍能注意要做的事情；不是放松到睡着，也不是带着反复分析错误和担忧的紧张状态进行。放松与想象可以结合使用。","原书以左右半球分工解释想象受紧张思维抑制的情形。这是本版教材的历史性说明；理解本节点应抓住“减少担忧与无关思维、维持清醒放松”，不把“大脑左半球只分析、右半球只想象”当作现代神经科学定论。"],"keywords":["清醒放松","减少担忧","放松与想象结合"],"explanation":"身体放松但头脑仍清醒，能持续跟随自己要演练的内容。"},{"id":"psy-imagery-cue","parentId":"psy-imagery-conditions","title":"（3）想象提示物。","kind":"point","original":true,"printedPages":[147],"body":["利用与项目相关的先兆或物体作为触发器，引出运动形象并提高想象能力，例如与专项情境有关的器材。提示物起到启动和提示作用，不能代替完整的想象练习。"],"keywords":["触发器","先兆或物体","启动想象"],"explanation":""},{"id":"psy-imagery-evaluation","parentId":"psy-imagery","title":"3. 想象技能评价","kind":"heading","original":true,"printedPages":[147],"body":["评价不能只看有没有视觉画面，还需检查声音、运动感觉、情绪体验与随意控制。多种感觉共同参与，才能较全面地判断想象质量。"],"keywords":["清晰度","颜色","声音","连贯活动","肌肉感觉","情绪体验","自主控制"],"explanation":""},{"id":"psy-imagery-eval-clarity","parentId":"psy-imagery-evaluation","title":"（1）想象中图像的清晰度。","kind":"point","original":true,"printedPages":[147],"body":["形象是否清楚，关键细节能否辨认。"],"keywords":["图像清晰"],"explanation":""},{"id":"psy-imagery-eval-color","parentId":"psy-imagery-evaluation","title":"（2）想象中图像的颜色。","kind":"point","original":true,"printedPages":[147],"body":["图像是否具备相应色彩和场景细节。"],"keywords":["颜色"],"explanation":""},{"id":"psy-imagery-eval-sound","parentId":"psy-imagery-evaluation","title":"（3）想象的情境中有无声音。","kind":"point","original":true,"printedPages":[147],"body":["是否包含与场景有关的听觉体验。"],"keywords":["声音"],"explanation":""},{"id":"psy-imagery-eval-continuity","parentId":"psy-imagery-evaluation","title":"（4）想象中图像的连贯性与活动性。","kind":"point","original":true,"printedPages":[147],"body":["动作过程是否连贯并具有动态变化，而非彼此割裂的静止片段。"],"keywords":["连贯性","活动性"],"explanation":""},{"id":"psy-imagery-eval-muscle","parentId":"psy-imagery-evaluation","title":"（5）想象中自我的肌肉运动感觉。","kind":"point","original":true,"printedPages":[147],"body":["是否能体验到身体运动及肌肉活动的感觉。"],"keywords":["肌肉运动感觉"],"explanation":""},{"id":"psy-imagery-eval-emotion","parentId":"psy-imagery-evaluation","title":"（6）想象中自我的情绪体验深度。","kind":"point","original":true,"printedPages":[147],"body":["能否体验与运动情境相应的情绪，而非只旁观画面。"],"keywords":["情绪体验深度"],"explanation":""},{"id":"psy-imagery-eval-control","parentId":"psy-imagery-evaluation","title":"（7）想象能否按照自己的意愿进行。","kind":"point","original":true,"printedPages":[147],"body":["能否按照任务要求开始、调整和控制想象过程。"],"keywords":["按意愿进行"],"explanation":""},{"id":"psy-relaxation","parentId":"psy-methods","title":"（三）放松技能","kind":"heading","original":true,"printedPages":[147,148,149],"body":["不必要的肌肉紧张会妨碍技能动作完成，还可能与情绪和心理紧张相互影响，增加能量消耗。这里介绍想象放松、逐渐放松和自我引导放松三种方法；重点是学会辨认并降低无益紧张。"],"keywords":["降低无益紧张","动作完成","想象放松","逐渐放松","自我引导放松"],"explanation":"","core":"放松服务于适宜的活动状态，不能简单等同于松懈或失去警觉。"},{"id":"psy-relax-imagery","parentId":"psy-relaxation","title":"1. 想象放松法","kind":"heading","original":true,"printedPages":[147,148],"body":["在舒适位置，以熟悉而能带来安全、舒适和放松感的情境为想象内容。配合呼吸，调动视觉、听觉、气味和身体感觉，使自己仿佛置身其中，以唤起放松体验。选取的情境应与个人曾有的舒适感受形成稳定联系。"],"keywords":["舒适情境","个人经验","多感觉","唤起放松"],"explanation":"它是用想象达到放松；与“演练动作技能”的想象训练在用途上不同。"},{"id":"psy-relax-progressive","parentId":"psy-relaxation","title":"2. 逐渐放松法","kind":"heading","original":true,"printedPages":[148],"body":["先体验身体某一局部肌肉的紧张，再学会解除这种紧张，逐步由局部扩展至全身，使运动员能分辨“紧张—放松”的差异并主动调节。","熟练后可把较多局部肌群逐渐合并为较少肌群，缩短达到放松状态所需时间。原书给出的持续秒数与周数是其示例程序，理解和作答时重点应是先辨认、后解除、由局部到整体的原理。"],"keywords":["先紧张后放松","感觉对比","局部到全身","逐步熟练"],"explanation":"先学会辨认肌肉什么时候在用力，再学会让无益的紧张消退。"},{"id":"psy-relax-self","parentId":"psy-relaxation","title":"3. 自我引导放松法","kind":"heading","original":true,"printedPages":[148,149],"body":["它是逐渐放松训练的简化形式。以缓慢轻松的呼吸配合自我引导语或想象，引导身体各肌群放松；开始时可按较完整脚本逐步练习，熟练后减少提示语和所需时间。脚本可由本人或他人念诵，语速缓慢、柔和，并在适当位置停顿。"],"keywords":["简化形式","呼吸","自我引导语","各肌群","熟练后缩短"],"explanation":"重点是运动员逐渐掌握可自行调用的放松程序，而非机械背诵一份长脚本。"},{"id":"psy-relax-script","parentId":"psy-relax-self","title":"自我引导放松练习（简化）脚本","kind":"point","original":true,"printedPages":[149],"body":["原书脚本的结构是：呼吸并提示“放松”→把注意转向额头和面部→体会并解除局部紧张→依次关注胳膊和双手、颈背、胸腹、大小腿与双脚→再次用呼吸和提示巩固全身放松。这是对脚本步骤的整理，不是原文逐字转录。想象放松与自我引导也可结合，原书另提及生物反馈等方法。"],"keywords":["呼吸提示","局部体验","全身放松","方法结合"],"explanation":"这里是练习示例，不应再与前面三种方法并列为“第四种放松法”。"},{"id":"psy-attention","parentId":"psy-methods","title":"（四）注意技能","kind":"heading","original":true,"printedPages":[149,150,151],"body":["注意是指人的心理活动对一定对象的指向和集中。","本部分分别讨论注意的指向性和注意的集中：前者解决从众多线索中选择什么，后者解决能否在需要的时间内维持对所选对象的关注。"],"keywords":["指向","集中","选择线索","维持注意"],"explanation":"","core":"先选对对象，再在任务需要的时间里维持；不是越用力想“我要集中”效果越好。","definition":"注意是指人的心理活动对一定对象的指向和集中。"},{"id":"psy-attention-direction","parentId":"psy-attention","title":"1. 注意的指向性","kind":"heading","original":true,"printedPages":[149,150],"body":["选择适宜刺激或线索，并过滤无关和对抗性刺激。专项任务不同，所需线索的内部/外部来源、广度以及选择次序也不同，应通过训练形成适宜的选择和反应。"],"keywords":["适宜线索","过滤干扰","内外","广狭","次序"],"explanation":"例如处理球时，既要看关键防守与空当，也要过滤与当前决策无关的观众声音。"},{"id":"psy-attention-dir-analysis","parentId":"psy-attention-direction","title":"（1）与运动员一起分析自己的运动项目中每一种特殊技能对注意的要求，确定这种注意究竟是内在的还是外在的，应该广阔到何种程度或狭窄到何种程度。","kind":"point","original":true,"printedPages":[149],"body":["确定任务需要内部还是外部注意，以及适宜的注意广度；先分析任务，再规定注意对象。"],"keywords":["任务分析","内部/外部","广阔/狭窄"],"explanation":""},{"id":"psy-attention-dir-sequence","parentId":"psy-attention-direction","title":"（2）当注意集中于外部时，要让运动员明白注意应该以何种次序指向何种线索，要尽可能地减少注意的线索和尽可能地使其明了。","kind":"point","original":true,"printedPages":[150],"body":["外部线索尽量精简、明确并有合理次序；内部注意则指向积极、建设性思维，避免消极担忧。"],"keywords":["外部线索次序","精简明确","积极思维"],"explanation":""},{"id":"psy-attention-dir-present","parentId":"psy-attention-direction","title":"（3）在实际完成某一种技能时，注意要指向当前正在完成的动作和马上就要完成的动作，而不是指向已经过去的比赛情况。","kind":"point","original":true,"printedPages":[150],"body":["把注意留在当前与即将执行的动作，不纠缠已经结束的比赛情况。"],"keywords":["当前","即将动作","不过度回顾"],"explanation":""},{"id":"psy-attention-dir-task","parentId":"psy-attention-direction","title":"（4）注意应集中在与任务有关的因素上，例如动作的结构和动作的实施，而不是集中在得分或悬而未决的结果上。","kind":"point","original":true,"printedPages":[150],"body":["关注动作结构与实施等任务相关因素，而不是得分和悬而未决的结果，避免获胜念头挤占执行下一动作所需注意。"],"keywords":["任务因素","动作实施","过程而非结果"],"explanation":""},{"id":"psy-attention-dir-filter","parentId":"psy-attention-direction","title":"（5）帮助运动员形成关于何种线索应该注意和何种线索应该过滤掉的心理定势和期望，然后让他们学会对这些线索的适宜反应。","kind":"point","original":true,"printedPages":[150],"body":["先建立线索选择规则，再学习对这些线索作出适宜反应。"],"keywords":["注意什么","过滤什么","适宜反应"],"explanation":""},{"id":"psy-attention-dir-prediction","parentId":"psy-attention-direction","title":"（6）在帮助运动员形成心理定势的同时，让运动员掌握那些可以帮助他们预测某些反应的线索，然后帮他们分析何时适宜作出预测反应。","kind":"point","original":true,"printedPages":[150],"body":["识别可用于预测的线索，并分析何时适宜作出预测反应；不能只求反应快而忽略判断依据。"],"keywords":["预测线索","反应时机"],"explanation":""},{"id":"psy-attention-dir-learning","parentId":"psy-attention-direction","title":"（7）在学习运动技能的时候，要让运动员的注意指向完成这些技能时他们肌肉内部的感觉和体会上。","kind":"point","original":true,"printedPages":[150],"body":["关注与技能学习有关的运动感觉，帮助形成运动知觉；想象也可以辅助传授这些感觉。此处针对原书所说技能学习情境，不应推成所有任务始终只能内部注意。"],"keywords":["运动感觉","技能学习","想象辅助"],"explanation":""},{"id":"psy-attention-dir-timing","parentId":"psy-attention-direction","title":"（8）在训练过程中，要在训练开始的时候趁运动员的心理能量还处在高水平时做那些需要注意的教学活动。","kind":"point","original":true,"printedPages":[150],"body":["把对注意要求较高的教学安排在运动员精力较充足的时候，考虑训练课内的时机。"],"keywords":["精力充足","教学时机"],"explanation":""},{"id":"psy-attention-dir-distraction","parentId":"psy-attention-direction","title":"（9）在训练过程中，当运动员初学某种运动技能时，要尽量减少分心因素，但是，稍后则要引进模拟竞赛的分心因素，这样才能训练运动员的注意技能。","kind":"point","original":true,"printedPages":[150],"body":["初学时降低干扰，随后逐步加入模拟竞赛的分心因素，使运动员学会在真实干扰中保持任务注意。"],"keywords":["初学减扰","逐步模拟","抗干扰"],"explanation":""},{"id":"psy-attention-dir-uncertainty","parentId":"psy-attention-direction","title":"（10）当外部环境中有大量的不确定性因素时，特别是那些运动员可能觉得对他们的自我价值是一种威胁的不确定性因素时，这种情况就会使他们产生紧张应激，也会增加他们分心的可能性。","kind":"point","original":true,"printedPages":[150],"body":["要重视不确定性和自我价值威胁引起的紧张应激及分心，帮助运动员理解情境并把注意重新放回任务。"],"keywords":["不确定性","自我价值威胁","紧张应激","分心"],"explanation":""},{"id":"psy-attention-concentration","parentId":"psy-attention","title":"2. 注意的集中","kind":"heading","original":true,"printedPages":[150,151],"body":["本节将注意集中限定为在一定时间内使注意维持在所选刺激上的能力，即注意的持续时间，不只指缩小注意范围。","应专注于此时此刻正在做的任务，训练维持时间应适应项目比赛要求。单纯紧张肌肉、反复命令自己“集中”，可能使注意转向“集中本身”；应减少紧张与不确定性，并在实际任务中练习。"],"keywords":["维持","持续时间","当前任务","项目要求"],"explanation":"“看对了什么”是指向性；“能持续看住、处理好它”是集中。"},{"id":"psy-attention-con-readiness","parentId":"psy-attention-concentration","title":"（1）由于注意的集中是一个被动的过程，这种技能的改进有些要通过让心理活动准备集中注意来实现，如摆脱紧张应激、沉醉于注意的目标等。","kind":"point","original":true,"printedPages":[151],"body":["按原书表述，“被动”强调不能仅凭强迫意念获得集中。应减少紧张应激、控制心理能量，让自己投入任务，形成有利于专注的准备状态。"],"keywords":["降低应激","投入任务","准备状态"],"explanation":""},{"id":"psy-attention-con-routine","parentId":"psy-attention-concentration","title":"（2）提高注意集中水平的另一个有效的途径就是运用临赛前程序，这种临赛前的程序如前所述可以降低不确定性、减少出现分心的潜在可能。","kind":"point","original":true,"printedPages":[151],"body":["通过稳定的临赛前程序降低不确定性，减少分心的可能；程序应为执行任务服务。"],"keywords":["临赛前程序","降低不确定性"],"explanation":""},{"id":"psy-attention-con-trigger","parentId":"psy-attention-concentration","title":"（3）注意集中的改进还可以采用动作触发器，即一些可以提醒运动员集中注意的词语和动作。","kind":"point","original":true,"printedPages":[151],"body":["使用能提醒运动员重新集中于任务的词语或动作，建立简明、可调用的注意提示。"],"keywords":["动作触发器","词语或动作"],"explanation":""},{"id":"psy-attention-con-practice","parentId":"psy-attention-concentration","title":"（4）注意的集中可以通过练习迅速得到提升。","kind":"point","original":true,"printedPages":[151],"body":["在训练课中安排与比赛实际持续时间和任务特点相适应的集中练习，避免只在少数环节短时练习。"],"keywords":["比赛要求","持续练习"],"explanation":""},{"id":"psy-attention-con-alertness","parentId":"psy-attention-concentration","title":"（5）在训练和竞赛中保持心理上的警觉性和控制心理能量不仅可以帮助运动员产生如剃须刀般锋利的注意的集中，而且还能获得更好的注意选择和转换技能。","kind":"point","original":true,"printedPages":[151],"body":["维持适宜警觉与心理能量，同时支持注意集中、线索选择和注意转换，不把放松误解为无精打采。"],"keywords":["警觉性","心理能量","选择","转换"],"explanation":""},{"id":"psy-will-training","parentId":"psy-methods","title":"（五）意志品质训练","kind":"heading","original":true,"printedPages":[151,152],"body":["意志品质就是能使我们去完成那些几乎不愿意承担的任务，甚至可能是讨厌的任务的一种品质。","运动员在训练竞赛困难中仍能为明确任务持续努力，需要平时培养主动性、毅力、进取心与拼搏精神；比赛表现会反映训练中养成的应对习惯。意志训练也需适当负荷和明确目标，不等于没有边界地硬撑。"],"keywords":["克服困难","持续努力","平时培养","明确任务","适当负荷"],"explanation":"不是一到比赛才要求“拼命”，而是在日常小任务中形成主动、认真、遇难不轻易放弃的习惯。","core":"七条建议把意志从口号落实为有目标、有动机、有任务的训练。","definition":"意志品质就是能使我们去完成那些几乎不愿意承担的任务，甚至可能是讨厌的任务的一种品质。"},{"id":"psy-will-small","parentId":"psy-will-training","title":"（1）从小问题着手。","kind":"point","original":true,"printedPages":[152],"body":["即使琐碎问题也有训练意义，可通过小任务培养认真落实和克服困难的习惯。"],"keywords":["小问题","日常习惯"],"explanation":""},{"id":"psy-will-desire","parentId":"psy-will-training","title":"（2）自己本身必须有解决问题的渴望。","kind":"point","original":true,"printedPages":[152],"body":["使运动员认同任务，形成主动解决问题的动机，而非始终依靠外部催促。"],"keywords":["主动渴望","解决问题"],"explanation":""},{"id":"psy-will-positive","parentId":"psy-will-training","title":"（3）学会运用积极思维使自己进入进攻状态。","kind":"point","original":true,"printedPages":[152],"body":["遇到困难任务先建立克服困难的勇气，用积极思维组织行动。"],"keywords":["积极思维","勇气","进攻状态"],"explanation":""},{"id":"psy-will-competition","parentId":"psy-will-training","title":"（4）将训练当作比赛，始终处于进攻状态，所有培养意志品质的练习都必须全力以赴。","kind":"point","original":true,"printedPages":[152],"body":["认真投入训练，避免敷衍形成消极习惯；“进攻状态”指主动应对困难的心理态度，不等于不顾计划无限增加负荷。"],"keywords":["训练当比赛","认真投入","避免敷衍"],"explanation":""},{"id":"psy-will-attention","parentId":"psy-will-training","title":"（5）要将全部的注意力集中指向当前的任务。","kind":"point","original":true,"printedPages":[152],"body":["把努力落实于当前可以完成的行动，减少对困难和结果的无效担忧。"],"keywords":["当前任务","注意集中"],"explanation":""},{"id":"psy-will-load","parentId":"psy-will-training","title":"（6）对毅力这种意志品质的训练并不需要进行得过于频繁。","kind":"point","original":true,"printedPages":[152],"body":["安排能够提高较长时间承受心理负荷能力的练习，同时合理控制频率。"],"keywords":["不过频","较长时间","心理负荷"],"explanation":""},{"id":"psy-will-goal","parentId":"psy-will-training","title":"（7）培养意志品质的练习和任务必须在心理上有一个明确的目标。","kind":"point","original":true,"printedPages":[152],"body":["让意志努力指向可辨认的目标，既不怕失败又争取成功，避免反复进行没有目的和成效依据的硬撑。"],"keywords":["明确目标","不怕失败","力争取胜"],"explanation":""},{"id":"psy-requirements","parentId":"tr4s2","title":"三、运动员心理训练的基本要求","kind":"heading","original":true,"printedPages":[152,153,154],"body":["四项要求回答如何把心理训练真正纳入训练体系：认识转为实践、自发转为自觉、零散转为系统、长期坚持并与其他训练贯通。"],"keywords":["付诸实践","自觉运用","系统运用","持之以恒","融会贯通"],"explanation":"","core":"训练方法列得再多，若不长期落实到日常训练，仍难形成稳定能力。"},{"id":"psy-require-practice","parentId":"psy-requirements","title":"（一）完成由感性认识到理性认识的飞跃，将心理训练付诸实践","kind":"heading","original":true,"printedPages":[152,153],"body":["不仅承认心理因素重要，还要理解心理训练原理、学习方法、安排实际训练。青少年和初级阶段同样需要心理训练，一些高水平比赛时暴露的问题可能与早期未重视有关，应与体能、技战术一起打好基础。"],"keywords":["理性认识","实际安排","青少年基础"],"explanation":"不是等水平高了、比赛失常了，才开始补心理训练。"},{"id":"psy-require-conscious","parentId":"psy-requirements","title":"（二）变自发使用为自觉运用","kind":"heading","original":true,"printedPages":[153],"body":["把凭经验临时使用、出了问题才处理，转为教练员在日常训练中有意识、有计划地传授和提高心理技能。心理专家可以协助，但不能代替教练员持续组织实施的责任；教练员的投入也影响运动员投入。"],"keywords":["有意识","有计划","日常训练","教练员实施"],"explanation":"专业协助有价值，平时的落实不能只等专家临赛救急。"},{"id":"psy-require-systematic","parentId":"psy-requirements","title":"（三）由个别、零散运用变成系统运用","kind":"heading","original":true,"printedPages":[153],"body":["全面理解训练内容，根据实际需要系统安排多种方法并持续练习，不能把心理训练等同于一两种方法，也不能按“心理因素占多大比例”机械切分训练时数。只尝试几次就期待奇效或放弃，无法形成整体训练效应。"],"keywords":["全面理解","系统安排","非机械比例","非速效"],"explanation":"“心理很重要”不能推导出把相同比例的训练时间孤立留给心理课。"},{"id":"psy-require-integrate","parentId":"psy-requirements","title":"（四）持之以恒，融会贯通，全面发展。","kind":"heading","original":true,"printedPages":[153,154],"body":["心理技能需要长期艰苦训练，并与体能、技术、战术训练相互依存、相互制约、相互促进。应有机结合、融为一体，全面发展竞技能力。教练员要理解心理训练，并使其成为日常训练计划不可缺少的组成部分。"],"keywords":["长期坚持","相互依存","有机结合","全面发展","日常计划"],"explanation":"可以在技术练习中加入注意线索，在模拟比赛中练情绪控制，使心理训练落在实际运动任务中。"},{"id":"know-overview","parentId":"tr4s3","title":"一、运动员知识能力概述","kind":"heading","original":true,"printedPages":[154,155,156,157,158,159],"body":["先明确知识能力的含义，再看它需要哪些学科知识，最后按不同标准区分运动知识。知识能力的落脚点是运用知识提高竞技运动水平。"],"keywords":["释义","构成","分类"],"explanation":"本部分回答“知识能力是什么、由什么知识支撑、知识可以怎样分类”。"},{"id":"know-meaning","parentId":"know-overview","title":"（一）运动员知识能力释义","kind":"point","original":true,"printedPages":[154],"body":["运动员知识能力是运动员竞技能力的重要组成部分。它是指运动员掌握和运用运动知识提高竞技运动水平的能力。掌握运动知识是运用运动知识的前提，运用运动知识，提高竞技运动水平是掌握运动知识的目的。"],"keywords":["掌握","运用","提高竞技运动水平"],"explanation":"会背概念只是掌握的一部分；能用知识发现问题、改进练习、提高比赛表现，才体现出能力。","core":"定义中的“掌握”和“运用”必须同时记住。","definition":"运动员知识能力是运动员竞技能力的重要组成部分。它是指运动员掌握和运用运动知识提高竞技运动水平的能力。"},{"id":"know-meaning-nature","parentId":"know-meaning","title":"理解角度一：运动知识本身的特点","kind":"point","original":false,"printedPages":[154],"body":["运动知识是人们在实践中获得的与运动相关的认识和经验。运动员掌握的相关知识应有助于提高体能、技战术和心理能力，并在比赛中创造优异成绩。同一内容既有感性成分，也有理性成分。"],"keywords":["认识和经验","感性","理性"],"explanation":"一次击球的感觉是经验；对用力与落点关系的认识带有理性分析。两者都可以构成运动知识。"},{"id":"know-meaning-access","parentId":"know-meaning","title":"理解角度二：运动知识的获得途径","kind":"point","original":false,"printedPages":[154],"body":["知识可以来自训练与比赛实践，也可以来自书本和教练员等他人的传授。运动员需要不断完善自己的知识结构；与肌肉活动相联系的操作部分，必须通过运动实践获得。"],"keywords":["运动实践","书本传授","操作部分"],"explanation":"别人可以讲清动作要领，却不能替你练出完成动作的能力。"},{"id":"know-meaning-use","parentId":"know-meaning","title":"理解角度三：运动知识产生作用的方式","kind":"point","original":false,"printedPages":[154],"body":["知识本身不会自动转化为运动成绩；只有合理运用，才能实现知识的价值。运动知识的运用，是利用已有知识提高竞技能力，并争取更好的比赛成绩。"],"keywords":["合理运用","竞技能力","比赛成绩"],"explanation":"知道为什么要做准备活动，还要会依据专项和个人状态安排并实施。"},{"id":"know-composition","parentId":"know-overview","title":"（二）运动员知识能力的构成","kind":"point","original":true,"printedPages":[154,155,156],"body":["知识结构包括各类知识形成的框架及各类知识的比重。运动员需要与优异成绩相关、合理优化的知识体系，既有精深的专门知识，也有广博的一般知识。","现代训练涉及多种学科，科学知识贯穿状态诊断、目标建立、计划制订、组织实施、检查评定和反馈调控，也参与恢复、选材、竞赛及管理。"],"keywords":["知识框架","知识比重","专门知识","一般知识"],"explanation":"本标题讲知识内容的结构，不是把所有知识只分成下面四个永不交叉的盒子。","core":"作答构成题：先答优化的知识体系，再展开相关学科及用途。","definition":"知识结构是指由各类知识形成的知识框架和各类知识的比重。"},{"id":"know-structure-pairs","parentId":"know-composition","title":"按不同标准认识知识结构","kind":"point","original":false,"printedPages":[154],"body":["自然科学知识与社会科学知识、普通知识与特殊知识、基础知识与专业知识、传统知识与现代知识，是依不同分类标准形成的知识类别。它们不能脱离各自标准混排为一套分类。"],"keywords":["不同标准","知识结构"],"explanation":"例如“运动生理学的基础理论”可以同时属于自然科学知识和基础知识；分类维度不同，身份可以重合。"},{"id":"know-bio","parentId":"know-composition","title":"1. 运动人体生物科学","kind":"point","original":true,"printedPages":[155],"body":["包括运动生理学、运动医学、运动生物化学、运动生物力学、人体动作技能学、运动解剖学和运动营养学等。","揭示形态结构、身体机能和运动素质在训练、比赛中的变化规律，阐明训练的生物学原理，为不同年龄、性别、项目及训练水平的训练实践提供依据。测试资料可用于负荷监控、疲劳与适应情况分析。"],"keywords":["形态结构","身体机能","运动素质","负荷监控"],"explanation":"这一类知识帮助回答“人体为什么这样反应、训练刺激是否合适”。具体指标需结合测试条件和其他信息分析，不能一项指标包办所有判断。","core":"把学科名称与其解决的训练问题一起记：人体变化规律及负荷、恢复的科学依据。"},{"id":"know-psy-education","parentId":"know-composition","title":"2. 运动心理学和体育教育学","kind":"point","original":true,"printedPages":[155],"body":["涉及认知方式、情绪控制、心态调整、人格修炼、文化素质和专项文化熏陶。研究技能学习、竞赛心理、运动动机及运动参与者之间的关系，也包括心理训练、心理辅导、咨询和健康教育。"],"keywords":["技能学习","情绪调节","行为控制","教育"],"explanation":"不仅要让运动员“能练”，还要理解他“怎样学、为什么练、如何调节”。","core":"将“怎样学习与调节”同人体生物学及群体关系问题区分。"},{"id":"know-humanities","parentId":"know-composition","title":"3. 体育人文社会学科","kind":"point","original":true,"printedPages":[155,156],"body":["揭示运动员价值观、人际关系、个体社会化，以及个体与群体行为在训练中的变化规律。研究成果有助于改善群体结构、放大系统功能、控制矛盾冲突、维护队伍秩序和加强群体互动。"],"keywords":["价值观","人际关系","社会化","群体互动"],"explanation":"关注运动员处在队伍和社会关系中怎样行动，不能仅理解为一个人的情绪变化。","core":"关键是价值观、社会化与群体关系，不仅是个人情绪。"},{"id":"know-other-science","parentId":"know-composition","title":"4. 其他科学领域","kind":"point","original":true,"printedPages":[156],"body":["材料学、气象学、计算机技术等，也与影响成绩的器械和运动环境有关。相关科学成果应根据训练任务和实际条件应用于训练、竞赛与管理。"],"keywords":["材料学","气象学","计算机技术"],"explanation":"例如器材特性、天气条件和信息处理，会影响训练安排和比赛准备。"},{"id":"know-classification","parentId":"know-overview","title":"（三）运动知识的分类","kind":"heading","original":true,"printedPages":[156,157,158,159],"body":["本部分先按知识解决的问题划分四个层面，再分别按动态与静态、能否清晰表述与有效转移划分两组知识。三套标准服务于不同问题，不能直接互相替代。"],"keywords":["解决的问题","动态与静态","表述与转移"],"explanation":"先问“按什么来分”，再记类别，就不会把程序性、显性和“为什么”并成同一级。","core":"本节最需要辨析的结构：三套不同的分类依据。"},{"id":"know-four-levels","parentId":"know-classification","title":"知识解决问题的四个层面","kind":"point","original":false,"printedPages":[156,157],"body":["四个层面的知识相辅相成。运动员不仅要会完成动作，还要认识相关事实、原理和信息来源，理解体能、技术、战术、心理之间的关系。对技能和诀窍的掌握很重要，但高水平运动员不能只有操作经验。"],"keywords":["是什么","为什么","怎么做","是谁的"],"explanation":"这套分类看知识在回答什么问题。第四层面原文说“谁知道某种信息”，应按信息由谁掌握理解，不要记成所有权概念。","core":"先说按解决的问题分类，再答四个层面及相辅相成的关系。"},{"id":"know-four-expressions","parentId":"know-classification","title":"描述、解释、操作与限定的表达层面","kind":"point","original":false,"printedPages":[156],"body":["描述性的知识说明“是什么”，解释性的知识说明“为什么”，操作性的知识说明“怎样做”，限定性的知识说明“是谁的”和时间等条件。","随后列举的四类知识，进一步从事实、自然原理和规律、技能诀窍、谁知道某种信息来展开。记忆时要保留其各自含义，不把“谁知道信息”误解成知识产权。"],"keywords":["描述","解释","操作","限定"],"explanation":"同一件训练现象，既可以被描述，也可以被解释，还可以进一步说明怎样操作及适用条件。这里的标签是原文内容，作为整理节点单列，非原有编号标题。"},{"id":"know-facts","parentId":"know-four-levels","title":"① 关于事实的知识：解决“是什么”","kind":"point","original":false,"printedPages":[156],"body":["描述有关事实、事物和现象，帮助运动员认识训练与比赛的对象。"],"keywords":["事实","是什么"],"explanation":"例如明确某种动作的名称、基本特征和比赛中的现象。"},{"id":"know-theory","parentId":"know-four-levels","title":"② 自然原理和规律方面的科学理论知识：解释“为什么”","kind":"point","original":false,"printedPages":[156],"body":["认识自然原理和规律，解释训练现象及其形成原因。"],"keywords":["原理","规律","为什么"],"explanation":"例如用生物力学知识分析动作怎样产生速度。"},{"id":"know-knowhow","parentId":"know-four-levels","title":"③ 关于技能和诀窍方面的知识：指导“怎么做”","kind":"point","original":false,"printedPages":[156],"body":["直接服务于完善的体能、完美的技术、灵活的战术和优良的心理素质，指导实际完成活动。"],"keywords":["技能","诀窍","怎么做"],"explanation":"会分析一个动作，不等于已经能熟练做出这个动作。"},{"id":"know-whoknows","parentId":"know-four-levels","title":"④ 谁知道某种信息的知识：指明“是谁的”","kind":"point","original":false,"printedPages":[156],"body":["明确谁掌握相关信息，从而获得适当的信息支持。"],"keywords":["信息来源","谁知道"],"explanation":"遇到技术分析、康复或营养问题时，知道应向哪位专业人员获取信息。"},{"id":"know-procedural-declarative","parentId":"know-classification","title":"（1）程序性运动知识和陈述性运动知识","kind":"heading","original":true,"printedPages":[157,158],"body":["从教育心理学角度，以动态和静态为标准，划分为动态操作形式的程序性知识与静态概念形式的陈述性知识。前者主要靠动作表达，后者主要靠语言表达。"],"keywords":["动态操作","静态概念","动作","语言"],"explanation":"判断这套分类，要看是在完成操作，还是在描述特征、关系与原理。","core":"这是动态操作与静态概念的分类标准，最容易与显性／隐性混用。"},{"id":"know-procedural","parentId":"know-procedural-declarative","title":"① 程序性运动知识","kind":"point","original":true,"printedPages":[157],"body":["程序性知识是关于怎样做的知识，涉及操作步骤和过程，这类知识主要用来解决“做什么”和“如何做”的问题，如通过动作表达出来的技术、战术本身。","运动技能由一系列动作操作构成。学习通常经过观摩示范建立视觉表象、反复练习建立并巩固动觉表象，逐渐达到动作自动化。其表现具有一定时间、空间和力量特征。"],"keywords":["怎样做","步骤和过程","动作操作","自动化"],"explanation":"看运动员能不能实际完成发球，考察的主要是程序性知识；让他说出动作要领，是另一种表达任务。","definition":"程序性知识是关于怎样做的知识，涉及操作步骤和过程，这类知识主要用来解决“做什么”和“如何做”的问题，如通过动作表达出来的技术、战术本身。","core":"“会做”需要真实操作与练习，不能由文字复述代替。"},{"id":"know-procedural-acquire","parentId":"know-procedural","title":"动作学习的形成过程","kind":"point","original":false,"printedPages":[157],"body":["观摩示范，建立视觉表象；通过反复练习建立和巩固动觉表象；在持续练习中逐步实现动作自动化。","学习中既要把握动作顺序，也要掌握身体位置、力量、幅度、方向、速度及各环节配合。"],"keywords":["观摩","视觉表象","动觉表象","自动化"],"explanation":"不是“看过就会”：看到动作、形成做动作的感觉、稳定完成，是相互衔接的学习过程。"},{"id":"know-declarative","parentId":"know-procedural-declarative","title":"② 陈述性运动知识","kind":"point","original":true,"printedPages":[157,158],"body":["陈述性知识是描述客观事物的特点及关系的知识，包括通过文字符号表达的、描述体能、技战术特点、说明其原理和相互间关系的知识。","它涉及“是什么”“为什么”“怎么样”，主要以文字或符号说明概念及概念之间的关系，用来区别、辨别事物。技术动作的概念、方法、分析、要领及作用、影响因素的文字论述，均可属于这一范围。"],"keywords":["特点及关系","文字符号","概念","原理"],"explanation":"写在纸上的“操作步骤说明”可以是对动作的陈述；真实完成动作才是操作能力的呈现，不能只凭出现“怎么”字判断。","definition":"陈述性知识是描述客观事物的特点及关系的知识，包括通过文字符号表达的、描述体能、技战术特点、说明其原理和相互间关系的知识。","core":"不仅背名称，还要说清特点、原理和概念间关系。"},{"id":"know-serve-example","parentId":"know-declarative","title":"排球正面下手发球的陈述性知识示例","kind":"point","original":false,"printedPages":[158],"body":["同一个发球动作，可以用动作概念、动作方法、动作技术分析和动作技术要领四种形式描述。它们分别承担界定动作、交代完成过程、解释动作依据及提炼操作重点的作用。"],"keywords":["概念","方法","技术分析","技术要领"],"explanation":"这四个标签是原文段首用语，整理为子节点便于对照；不是另一套与程序性、陈述性并列的分类。"},{"id":"know-serve-concept","parentId":"know-serve-example","title":"动作概念","kind":"point","original":false,"printedPages":[158],"body":["界定面对球网、手臂由后下方向前摆动，在腹前将球击入对方场区的发球方式。"],"keywords":["界定动作","基本特征"],"explanation":"先说明这个动作是什么。"},{"id":"know-serve-method","parentId":"know-serve-example","title":"动作方法","kind":"point","original":false,"printedPages":[158],"body":["按准备姿势、抛球、击球和击球后入场等顺序描述完整操作过程，交代身体姿势和重心变化。"],"keywords":["准备","抛球","击球","入场"],"explanation":"方法是“完整怎么做”，比口诀更具体。"},{"id":"know-serve-analysis","parentId":"know-serve-example","title":"动作技术分析","kind":"point","original":false,"printedPages":[158],"body":["分析肩关节为轴的直臂摆动、击球前不屈肘等动作要求与挥臂速度、出手角度、路线及准确性的关系。"],"keywords":["动作要求","效果依据"],"explanation":"分析是解释“这样做有什么作用”，不能只复述动作顺序。"},{"id":"know-serve-cues","parentId":"know-serve-example","title":"动作技术要领","kind":"point","original":false,"printedPages":[158],"body":["从完整方法与分析中提炼抛球、摆臂、击球时机和击球部位等关键提示，帮助练习中抓住重点。"],"keywords":["关键提示","操作重点"],"explanation":"要领是把复杂动作压缩成练习时容易想起的提示。"},{"id":"know-explicit-tacit","parentId":"know-classification","title":"（2）显性运动知识和隐形运动知识","kind":"heading","original":true,"printedPages":[158,159],"body":["根据知识能否清晰地表述和有效地转移，可以分为显性知识和隐性知识。竞技体育中，隐性知识体现为完成动作的实践经验，显性知识可体现为对动作的语言描述。","原书本小标题印为“隐形运动知识”，正文统一讨论“隐性运动知识”。本知识树保留标题原貌，解释中使用“隐性”。"],"keywords":["清晰表述","有效转移","显性","隐性"],"explanation":"这套分类重点在知识如何表达、交流，不是重新把知识按学科来源分一次。","core":"分类依据是清晰表述与有效转移；原书小标题“隐形”与正文“隐性”须辨明。"},{"id":"know-tacit","parentId":"know-explicit-tacit","title":"① 隐性运动知识","kind":"point","original":true,"printedPages":[158,159],"body":["运动员能够做出的事情，不一定能清楚地用语言表达。技术、战术、心理调适、观察判断和迅速决策中，难以完整言传的经验，属于隐性运动知识。","它既包括技能、技巧、经验和诀窍，也包括价值观、心智模式、队员默契和组织运动文化等认知方面的成分；具有情境性、个体性，常表现为“凭感觉”或难以描述的动作力量与节奏。"],"keywords":["难以言传","实践经验","情境性","个体性"],"explanation":"隐性不等于不存在或不科学，意思是“会做但未必说得清”；也不只限于肌肉动作。","core":"难言传不等于无知识，认知与团队默契也可有隐性成分。","definition":"在竞技体育中，隐性运动知识则是运动员完成动作的实践经验，显性知识是对动作的语言描述。"},{"id":"know-explicit","parentId":"know-explicit-tacit","title":"② 显性运动知识","kind":"point","original":true,"printedPages":[159],"body":["那些可以用语言或地图、数学公式来表述的运动知识属于显性知识，如通过文字语言形式表达的各个专项独立的、项群的，或涵盖各个专项的训练和比赛的过程特点。","它有助于表达、记录和交流对训练与比赛的认识。同一个动作既可以有运动员的动作经验，也可以有概念、要领和原理的语言描述。"],"keywords":["语言","地图","数学公式","表达交流"],"explanation":"能写出或讲清楚动作及其关系，有利于共享知识，但不能代替亲自练习。","definition":"那些可以用语言或地图、数学公式来表述的运动知识属于显性知识，如通过文字语言形式表达的各个专项独立的、项群的，或涵盖各个专项的训练和比赛的过程特点。","core":"清晰表达有助于交流，仍要与个人实践相结合。"},{"id":"know-conversion","parentId":"know-explicit-tacit","title":"一定条件下隐性知识向显性知识转化","kind":"point","original":false,"printedPages":[159],"body":["运动知识依存于具体情景与个体，也随认识深化而变化。在一定条件下，隐性运动知识可以转化为显性知识，这也是运动员知识能力提高的标志之一。"],"keywords":["一定条件","认识深化","隐性到显性"],"explanation":"练习后比较成功与失败的动作，找到重心和击球的关系并讲清楚，就是把经验提炼出来；不能理解成所有感觉都能一次完整说清。","core":"注意“一定条件下”；转化需要反思、比较、分析和表达。"},{"id":"know-acquisition","parentId":"tr4s3","title":"二、运动员知识能力的获得与提高","kind":"heading","original":true,"printedPages":[159,160,161,162,163],"body":["运动员知识的增长同时包含隐性与显性两部分。获得与提高知识能力，应结合指导者传授、生活与学校学习、训练实践以及专业理论学习，不能只把增长理解为多读书。"],"keywords":["显性增长","隐性增长","多种途径"],"explanation":"","core":"获得不只有显性理论增长，也包括隐性经验的积累与加工。"},{"id":"know-team","parentId":"know-acquisition","title":"（一）从训练团队的指导者获得知识能力","kind":"heading","original":true,"printedPages":[160],"body":["训练团队既提供动作示范与语言指导，也通过科研监控与专业服务帮助运动员理解训练和比赛。不同指导方式提供的知识表达形式有所侧重，需要相互配合。"],"keywords":["示范","语言提示","科研传授"],"explanation":"","core":"每种方式都按“提供什么—怎样学习—如何运用”来回答。"},{"id":"know-demonstration","parentId":"know-team","title":"1. 教练员的示范","kind":"point","original":true,"printedPages":[160],"body":["很多动作不便完全用语言传授，教练员通过示范展现自己的隐性知识。运动员观察、模仿和练习，学习动作如何完成，并在模仿练习中运用教练员展现的知识。"],"keywords":["观察","模仿","练习","隐性知识"],"explanation":"动作示范主要让你“看见怎么做”；示范必须结合实际练习，才能成为自己的能力。"},{"id":"know-verbal","parentId":"know-team","title":"2. 教练员的语言提示","kind":"point","original":true,"printedPages":[160],"body":["教练员用语言准确提示动作特点与要领，说明各环节的联系；也可进一步讲解生物力学、生理学和心理学机制。运动员经聆听、分析和实践，把语言知识用于练习，提高技术动作水平。"],"keywords":["特点要领","环节联系","原理","聆听分析实践"],"explanation":"语言提示可以把需要注意的地方说清；“听懂了”后仍须在动作中检验。"},{"id":"know-research-team","parentId":"know-team","title":"3. 教练团队科研人员的知识传授","kind":"point","original":true,"printedPages":[160],"body":["科研人员通过专项训练、生理生化、营养恢复、体重控制、高原训练和心理调控等研究与监测，为运动员提供科学认识及训练服务。个体资料帮助识别运动员特点，支持训练、恢复和比赛发挥。"],"keywords":["科研监控","个人特点","训练恢复","专业服务"],"explanation":"科研数据的价值在于帮助认识和解决具体问题，不能只记住一串数值。"},{"id":"know-life-study","parentId":"know-acquisition","title":"（二）从生活、学习环境中获得知识能力","kind":"heading","original":true,"printedPages":[160,161],"body":["生活环境提供广泛信息与经验，学校教育和书本学习则有目的、有计划、有系统地发展知识及认识能力。"],"keywords":["生活环境","学校教育","书本知识"],"explanation":""},{"id":"know-life","parentId":"know-life-study","title":"1. 来自生活环境","kind":"point","original":true,"printedPages":[160,161],"body":["社会环境影响运动员的个体发展，尤其是心理发展。电视、广播、报刊、网站等多元媒体提供信息；能否从中获得有价值的知识，还取决于个人兴趣与学习的积极主动性。"],"keywords":["社会环境","多元媒体","兴趣","主动性"],"explanation":"身处同样的信息环境，主动观察、提问的人可能获得更多知识。"},{"id":"know-school","parentId":"know-life-study","title":"2. 来自学校教育和书本知识","kind":"point","original":true,"printedPages":[161],"body":["学校教育使运动员在较短时间内系统掌握知识技能，并形成相应观点、信念和行为习惯。语文学习发展表达、观察与概括，数学学习发展逻辑思维、分析与推理。","物理、化学、生物等学习为理解运动现象和教练员意图提供条件；体育专业课程进一步提供专项知识、一般基础知识和原理，帮助运动员分析体能、技术、战术与心理训练。"],"keywords":["系统学习","表达概括","逻辑推理","基础和专业"],"explanation":"文化学习既补充知识，也发展用来总结经验和理解训练的思维工具。原书中的个别生理举例具有出版时背景，学习本节点应抓住教育作用，勿把例子扩展为通用医学结论。","core":"文化学习既提供知识，也提供表达、概括、分析和推理工具。"},{"id":"know-practice","parentId":"know-acquisition","title":"（三）从运动训练实践中获得知识能力","kind":"heading","original":true,"printedPages":[162],"body":["训练实践既产生动作经验，也为分析、总结经验提供材料。通过反复练习与比较，可以把部分原来难以表达的经验提炼成显性知识。"],"keywords":["实践产生经验","加工提炼"],"explanation":""},{"id":"know-practice-tacit","parentId":"know-practice","title":"1. 来自实践的隐性运动知识","kind":"point","original":true,"printedPages":[162],"body":["按照示范与语言指导完成动作，是运用知识的实践过程，同时发展技术并获得隐性知识。运动员处理具体来球时，根据特定情境、任务和个人经验采取行动，体现隐性知识的情境性和个体性。"],"keywords":["特定情境","特定任务","个人经验"],"explanation":"会在真实来球中调整步法和击球，往往比复述固定动作说明复杂。"},{"id":"know-process-tacit","parentId":"know-practice","title":"2. 对自身隐性知识的加工","kind":"point","original":true,"printedPages":[162],"body":["通过反复练习加深对自己动作的意识，比较成功与失败动作，分析、归纳动作要素间的关系，把原来难以表达的经验转为别人能够理解的形式。","例如通过比较击球，归纳步法、身体重心和击球之间的关系，使原来的隐性经验成为可用语言表述的知识。"],"keywords":["反复练习","成功失败比较","分析归纳","显性描述"],"explanation":"关键是从“这次凭感觉打好了”，进一步找出“什么条件下更容易打好，为什么”。","core":"成功失败比较和分析归纳，是从感觉到可解释经验的关键中间环节。"},{"id":"know-professional-study","parentId":"know-acquisition","title":"（四）通过专业知识学习提高运动员知识水平","kind":"heading","original":true,"printedPages":[162,163],"body":["专业理论学习既遵循一般知识学习方法，也必须与运动员自己的训练实践结合；同时要学习相关学科，并在实践中形成体能、技战术和心理能力。"],"keywords":["一般方法","结合实践","多学科","程序性部分"],"explanation":"","core":"一般学习方法之外，突出结合本人的训练实践这一特殊要求。"},{"id":"know-study-methods","parentId":"know-professional-study","title":"1. 学习文化理论知识的一般方法","kind":"point","original":true,"printedPages":[162],"body":["可采用阅读自学、教师讲解辅导、小组讨论、完成作业和专题研究等，根据文化水平与学习条件选择适宜形式。","学习内容多为概念与命题构成的陈述性知识，也涉及技术规则的程序性说明；可通过口头传授、书刊、视听媒体、软件与数据库等获得。认知活动中同样存在洞察力、直觉和团队默契等隐性成分。"],"keywords":["阅读自学","讲解辅导","小组讨论","作业研究"],"explanation":"学习形式不是知识分类标准；小组讨论既能交流理论，也能帮助把经验讲清。"},{"id":"know-combine-training","parentId":"know-professional-study","title":"2. 结合训练实践学习体育专业理论知识","kind":"point","original":true,"printedPages":[162,163],"body":["专业理论学习的特殊要求是紧密结合训练实践并取得实际效果，尤其要联系自己的训练。认真理解训练计划、记好训练日记、进行训练总结，带着问题学习和思考。","还应观察研究同伴、对手及国内外优秀运动员的实践，科学分析比较，发现训练成功的规律。把理论概念用于实践，并与个人经验结合，可形成新的隐性知识。"],"keywords":["训练计划","训练日记","训练总结","观察比较","理论用于实践"],"explanation":"读到一条理论后，回到自己的训练记录中找例子，再设计练习去检验，才能知道自己是否真会运用。","core":"训练计划、训练日记、训练总结，是理论与自己训练连接的具体抓手。"},{"id":"know-multidisciplinary","parentId":"know-professional-study","title":"3. 广泛学习相关学科的科学知识","kind":"point","original":true,"printedPages":[163],"body":["除本专项理论外，还需学习运动生理学、运动解剖学、运动心理学、体育社会学、体育美学等有关理论。多领域知识有助于科学组织训练并成功参加竞赛。"],"keywords":["专项理论","相关学科","科学训练"],"explanation":"“专业”不是只懂一个项目的动作口诀，许多训练问题需要多个学科共同解释。"},{"id":"know-abilities-practice","parentId":"know-professional-study","title":"4. 体能、技战术、心理能力的获得","kind":"point","original":true,"printedPages":[163],"body":["这里强调的是体能、技战术、心理能力的实践部分，即程序性知识部分。它深植于个人长期训练和比赛的经验，具有高度个体化、不易言传和模仿的特点。","它与运动员的个人经历、性格和修养相关，体现为运动中的技能、技巧、经验、诀窍，以及直觉、灵感、洞察力、信念、价值观和心智模式等。"],"keywords":["实践部分","程序性知识","长期积累","个体化"],"explanation":"理论可以指导训练，但最终能否完成动作、调节状态，还要靠本人长期训练形成。"},{"id":"know-application","parentId":"tr4s3","title":"三、运动员知识能力的运用","kind":"heading","original":true,"printedPages":[163,164],"body":["本部分由应用意识、赛前赛后反思、实践迁移三个方面展开。知识能力在学习、实践、再学习、再实践的循环中提高。"],"keywords":["自觉应用","分析总结","实践迁移"],"explanation":"","core":"主动应用、分析反思、实践迁移，三方面共同完成知识到能力的转化。"},{"id":"know-conscious","parentId":"know-application","title":"（一）提高应用理论知识的自觉性","kind":"point","original":true,"printedPages":[163],"body":["教练员和运动员先明确专业理论知识的作用，再主动应用于自己的训练。可以从实践需要出发寻找理论，也可以从系统学习中发现改进实践的思路。","教学训练中增加“提问—讨论—讲评”，引导运动员观察、分析自己的行为，从被动接受转为主动获取，发展观察、分析与判断能力。"],"keywords":["主动应用","实践到理论","理论到实践","提问讨论讲评"],"explanation":"这不是只要求态度积极，而是要求建立具体的“问题—学习—运用”路径。","core":"两条应用路径按起点区分，最终都要回到实践解决问题。"},{"id":"know-practice-to-theory","parentId":"know-conscious","title":"路径一：由实践到理论","kind":"point","original":false,"printedPages":[163],"body":["从训练中的实际需要或问题出发，学习、理解并掌握相关理论，再用于解决训练问题。学习目的明确、运用针对性强。"],"keywords":["实际问题","寻找理论","针对性"],"explanation":"例如为了使负荷控制更准确，先提出监控问题，再学习适宜的检测与解释方法，并结合项目条件应用。"},{"id":"know-theory-to-practice","parentId":"know-conscious","title":"路径二：先理论，后实践","kind":"point","original":false,"printedPages":[163],"body":["在系统理论学习中发现新的认识，主动改进训练。原书以艺术体操教练员学习不对称图形的美学价值后调整成套动作编排为例。"],"keywords":["理论启发","主动改进"],"explanation":"这条路的起点是理论中的新发现，最终仍要回到实践检验。"},{"id":"know-reflection","parentId":"know-application","title":"（二）认真做好赛前分析和赛后总结","kind":"point","original":true,"printedPages":[163,164],"body":["赛前集体分析技战术及对手竞技能力特征，赛后及时总结成败原因。科学总结使理论认识更深、实践解析更准，并揭示事物间的联系。","经验总结既是隐性知识显性化的语言过程，也是自我反思过程。运动员可以自行反思，也可由教练员协助；训练和比赛后与队友交流，有助于表达内隐观点，并让经验被自己及他人认识。"],"keywords":["赛前分析","赛后总结","语言表达","自我反思","交流"],"explanation":"总结不是只记输赢或感受，而是把“当时怎么做、为何这样做、结果如何、下次怎样调整”说明白。","core":"总结要揭示成败原因和联系，并通过交流、反思促进隐性经验显性化。"},{"id":"know-practice-application","parentId":"know-application","title":"（三）在实践运用中提高知识能力","kind":"heading","original":true,"printedPages":[164],"body":["将获得的经验与知识不断用于训练和比赛，在反复运用中检验、深化并改进知识。其内容包括自己的经验、他人的成功经验以及有关科研成果。"],"keywords":["自身经验","他人经验","科研成果"],"explanation":"","core":"自己的经验、他人的经验、科研成果，来源不同，都需实践运用和检验。"},{"id":"know-own-experience","parentId":"know-practice-application","title":"1. 总结应用自身的实践经验","kind":"point","original":true,"printedPages":[164],"body":["回顾既有经验，分析其积极或消极作用，并据此对后续训练和比赛作出设想，再在实践中应用。"],"keywords":["回顾","分析作用","未来设想","再应用"],"explanation":"从一次失败中找到能调整的因素，并在下一次训练中验证，才完成了应用。"},{"id":"know-others-experience","parentId":"know-practice-application","title":"2. 学习应用他人的成功经验","kind":"point","original":true,"printedPages":[164],"body":["把教练员、其他运动员的实践经验用于自己的训练和比赛。将示范和语言提示落实到实际动作，经大量练习形成熟练、连贯的操作，使其成为个人的隐性知识。"],"keywords":["示范提示","实际动作","大量练习","个人经验"],"explanation":"借鉴不是照抄结果，必须经过本人的练习和适应。"},{"id":"know-research-application","parentId":"know-practice-application","title":"3. 学习应用有关科研成果","kind":"point","original":true,"printedPages":[164],"body":["将专业人员研究成果用于训练与比赛，例如运用营养知识安排食物、依据机体工作原理安排准备活动与整理恢复。应用时应结合具体对象、任务和条件，并检查实际效果。"],"keywords":["专业研究","训练比赛","结合条件","效果检验"],"explanation":"本节点学习“把科学知识用于实践”的路径；原书关于乳酸、酸痛和补碱食物的具体举例不宜泛化成个人恢复处方。"}],"questions":[{"id":"psy-q-definition","prompt":"名词解释：运动员心理能力。","examType":"term","nodeIds":["psy-definition"],"printedPages":[141],"answer":["运动员心理能力即指运动员与训练竞赛有关的个性心理特征，以及依训练竞赛的需要把握和调整心理过程的能力，是运动员竞技能力的重要组成部分。"],"keywords":["个性心理特征","把握和调整心理过程","竞技能力的重要组成部分"],"explanation":"定义按“涉及哪些特征—具备何种调节能力—在竞技能力中的地位”理解，参考定义保持原文。","sourceType":"original-simulation","definitionVerbatim":true,"highlights":["个性心理特征","把握和调整心理过程","竞技能力的重要组成部分","竞技能力","动员"]},{"id":"psy-q-classifications","prompt":"心理训练中的“基础与专门”“日常与赛期”是同一套分类吗？请说明分类依据、任务和联系。","examType":"short","nodeIds":["psy-training","psy-content-class","psy-basic","psy-targeted","psy-period-class","psy-competition","psy-daily"],"printedPages":[142,143],"answer":["一、两套分类依据不同。基础与专门心理训练主要按内容及针对性划分；日常与赛期心理训练依据与训练、比赛的关系划分，不能将二者机械地一一对应。","二、基础心理训练又称一般心理训练，发展训练竞赛必需的基本心理素质，包括心理技能、专项心理素质和良好个性品质。有针对性的心理训练又称专门心理训练，为具体比赛做好准备，或围绕特定心理问题展开。","三、日常心理训练相对侧重心理技能发展和个性心理特征改善；赛期心理训练侧重特定比赛的心理过程调整，包括赛前准备、赛中控制、赛后调整。","四、两套分类从不同角度安排同一训练体系。基础技能应在日常逐步建立，并在赛期按具体任务调用；具体问题也可以提前在日常训练中有针对性地解决。"],"keywords":["分类依据不同","基础/专门","日常/赛期","三阶段","不能一一对应"],"explanation":"先说明两套分类的标准，再逐套交代类别与任务，最后解释交叉联系。这样不把“四个词”误列为同一级四类。","sourceType":"original-simulation","highlights":["分类依据不同","两套分类","基础心理训练","一般心理训练","有针对性的心理训练","专门心理训练","基本心理素质","心理技能","专项心理素质","个性品质","具体比赛","赛前准备","日常","心理过程","个性心理特征","赛中控制","赛后调整"]},{"id":"psy-q-competition","prompt":"运动员体能、技术和战术准备较充分，仍在重要比赛中发挥失常。简述赛前、赛中、赛后应分别安排哪些心理训练任务。","examType":"short","nodeIds":["psy-competition","psy-before","psy-during","psy-after"],"printedPages":[142],"answer":["一、赛前做好心理准备。激发比赛动机，调节适宜激活水平，增强参赛信心，建立稳定而灵活的参赛思维和行为程序。把准备落实到可执行的比赛任务，减少无序担忧。","二、赛中实施心理控制。面对环境与比赛进程变化，保持良好稳定情绪，将注意重新放回当前任务，使已有体能、技能和战术能力得到发挥。","三、赛后区别情况调整。对成功者肯定积极体验，同时查找被胜利掩盖的问题，防止自满松懈；对失败者缓解消极体验，发现局部积极表现，重新激发求胜动机。","四、三个阶段应连贯安排，不能只做一次赛前动员。赛后调整形成的经验可反馈到后续日常训练与下一次比赛准备。"],"keywords":["赛前准备","赛中控制","赛后调整","成功/失败区别","连续安排"],"explanation":"沿比赛时间顺序组织，赛后再分成功者、失败者两条，既覆盖阶段又体现对象差异。","sourceType":"original-simulation","highlights":["赛后调整","动机","激活水平","信心","行为程序","成功者","失败者","积极体验","自满松懈"]},{"id":"psy-q-factors","prompt":"简述影响运动员心理能力的主要因素及其具体表现。","examType":"short","nodeIds":["psy-factors","psy-factor-personality","psy-factor-emotion","psy-factor-attention","psy-factor-perception","psy-factor-motivation","psy-factor-will","psy-factor-confidence","psy-factor-fatigue"],"printedPages":[143],"answer":["一、个性特征，包括性格倾向性、精神质（适应力）和情绪稳定性；竞赛情绪，包括赛前情绪和竞赛状态焦虑水平。","二、注意特征，包括分配、广度、稳定性和转移；感知觉能力，包括速度知觉和反应能力。","三、比赛动机水平，包括赛前动机水平及其变化趋势；意志品质，包括主动性、果断性、坚韧性、自制性和自觉性。","四、自信水平，包括一般自信、特质自信和状态自信；中枢神经疲劳，主要通过运动员自我感受的测试判定。"],"keywords":["个性","情绪","注意","感知觉","动机","意志","自信","中枢神经疲劳"],"explanation":"八项按四组配对便于记忆，但每组只是背诵编排，不是书上新增的上位分类；作答保留全部八项。","sourceType":"original-simulation","highlights":["个性","情绪","注意","感知觉","动机","意志","自信","中枢神经疲劳","疲劳","性格倾向性","精神质（适应力）","情绪稳定性","赛前情绪","竞赛状态焦虑","分配","广度","稳定性","转移"]},{"id":"psy-q-goal-principles","prompt":"简述科学设置运动员训练与竞赛目标应考虑的主要因素。","examType":"short","nodeIds":["psy-goals","psy-goal-performance","psy-goal-challenge","psy-goal-realistic","psy-goal-specific","psy-goal-time","psy-goal-individual"],"printedPages":[143,144,145],"answer":["一、以表现目标为重点。把成功要求落实到运动员可控制的自身表现，避免仅以胜负、名次评价训练和竞赛。","二、难度应有挑战且符合实际。目标应足以激发努力，同时以真实水平为起点，避免过易而无推动力，或过难而削弱动机；根据进程适当调整。","三、目标必须具体。明确成功标准，尽可能数量化，并限定时间或事件，才能指导行动和核对完成情况。","四、短期与长期结合。用可检查的近期任务逐步推进长期方向，通过反馈、成功体验和计划调整维持努力；以长远发展看待单次比赛，减轻过度紧张。","五、个体与全队结合。明确个人可控制的任务和责任，在集体项目中以个体目标支撑全队合作，并预防个人追求与团队要求冲突。"],"keywords":["表现","挑战","现实","具体","长短结合","个体与全队"],"explanation":"原书六组考量在答案中合为五点：第二点同时覆盖挑战性和现实性，二者相关却不相同，核对时不能漏任何一项。","sourceType":"original-simulation","highlights":["表现","挑战","具体","个体与全队","表现目标","动机","真实水平","适当调整","成功标准","数量化","时间或事件","可检查","长期方向","全队合作","结合"]},{"id":"psy-q-goal-case","prompt":"某队目标是“下一场必须夺冠，每人尽最大努力”，训练后仅按输赢奖惩。请分析目标设置的问题，并提出修改思路。","examType":"essay","nodeIds":["psy-goals","psy-goal-performance","psy-goal-challenge","psy-goal-realistic","psy-goal-specific","psy-goal-time","psy-goal-individual"],"printedPages":[143,144,145],"answer":["一、问题首先在于只设结果目标。夺冠还受对手、赛程等因素影响，不能完全由自身控制；仅按输赢评价，容易忽视实际进步和任务执行。应把全队期望转化为可控制的表现要求。","二、“尽最大努力”缺少检查标准。应依据项目和队员真实水平，明确某项技术、配合或执行质量的成功标准，限定训练周期或比赛事件，形成可记录、可反馈的具体目标。","三、难度需有挑战且现实。不能因夺冠愿望强烈就跳过能力分析；应与运动员共同商定努力后可能达到的要求，随训练进程滚动调整，避免过易或长期无法完成。","四、以阶段任务支持长远方向。保留全队长期追求，同时设置近期训练和本场比赛的执行目标，通过阶段反馈发现不足、安排修正，不把单次输赢当成全部价值。","五、全队目标必须落实到个人责任。根据位置和任务划分队员各自可控制的表现要求，使个人努力共同服务团队，并检查个人数据追求是否损害配合。","六、评价兼顾执行过程与结果。既复盘胜负，也核对具体表现目标和努力质量，以反馈指导下一轮训练，形成目标—行动—评价—调整的连续过程。"],"keywords":["结果不完全可控","笼统缺标准","真实水平","阶段目标","个人责任","反馈调整"],"explanation":"采用“发现问题—解释为什么—对应修改”的结构；例题没有给队员基础数据，因此不臆造适用于所有队伍的数值指标。","sourceType":"original-simulation","highlights":["真实水平","个人责任","自身控制","表现目标","结果目标","成功标准"]},{"id":"psy-q-imagery-definition","prompt":"名词解释：想象技能。","examType":"term","nodeIds":["psy-imagery"],"printedPages":[145],"answer":["想象技能是指运动员利用头脑中已形成的运动表象进行训练的一种技能。"],"keywords":["已形成的运动表象","进行训练"],"explanation":"把定义中的“表象基础”和“用于训练”两部分记牢；放松中的情境想象只是想象的一种用途。","sourceType":"original-simulation","definitionVerbatim":true,"highlights":["已形成的运动表象","进行训练","运动表象"]},{"id":"psy-q-imagery-stages","prompt":"简述想象技能的主要作用及其发展的三个阶段。","examType":"short","nodeIds":["psy-imagery","psy-imagery-stages","psy-imagery-stage-sense","psy-imagery-stage-vivid","psy-imagery-stage-control"],"printedPages":[145,146],"answer":["一、主要作用。帮助运动员获得和练习复杂动作技能，演练特殊比赛技术与战术，并获得其他心理技能。想象围绕已有运动表象进行，服务于实际训练竞赛。","二、感觉意识阶段。使运动员清楚体验完成动作时的身体位置、脚步、节奏、方向变化以及视觉、动觉、听觉等，为内部演练提供经验材料。","三、鲜明生动性阶段。把各种感觉组织为清楚、生动的形象；基础较差时从熟悉简单场景开始，逐步变化并与专项动作联系。","四、控制性阶段。学习按任务需要操纵想象内容，使动作和情境演练能够朝所需过程与结果进行，再逐步用于运球、投篮、防守等专项任务。"],"keywords":["三项作用","感觉意识","鲜明生动性","控制性","经验到控制"],"explanation":"先回答“为什么练”，再按“有体验—形象清楚—能按需要控制”的递进回答“如何发展”。","sourceType":"original-simulation","highlights":["感觉意识","鲜明生动性","控制性","运动表象","复杂动作","心理技能","视觉","动觉","听觉","鲜明生动"]},{"id":"psy-q-imagery-evaluate","prompt":"运动员说“脑中能看见动作，就说明想象训练很好”。请辨析，并说明想象训练的准备条件与评价维度。","examType":"short","nodeIds":["psy-imagery-conditions","psy-imagery-background","psy-imagery-relaxed","psy-imagery-cue","psy-imagery-evaluation"],"printedPages":[146,147],"answer":["一、这种判断不全面。想象不是单一视觉画面，而是多种感觉和情绪参与的综合体验，还需要按自身意愿控制。能看见动作只能说明其中一个方面。","二、准备背景。初学者先在分心因素较少的环境练习，随技能发展逐步进入复杂情境，学会过滤干扰，而不是永远依赖安静环境。","三、准备状态与提示。练习前保持清醒的身心放松状态，减少担忧和无关思维；必要时用项目相关的先兆或物体作提示物，帮助启动运动形象。","四、评价形象质量。检查图像清晰度、颜色、有无声音，以及图像的连贯性和活动性。","五、评价自身体验与控制。检查肌肉运动感觉、情绪体验深度，以及能否按照自己的意愿进行想象。上述维度应共同使用，避免只看“有没有画面”。"],"keywords":["多感觉","背景","清醒放松","提示物","四项形象质量","感觉情绪控制"],"explanation":"先纠正观点，再分“练前怎么准备”和“练得怎样如何评价”；注意三条件与七评价是不同层次。","sourceType":"original-simulation","highlights":["背景","提示物","过滤干扰","减少担忧","先兆或物体","清晰度","颜色","声音","情绪体验"]},{"id":"psy-q-relax-methods","prompt":"比较想象放松法、逐渐放松法与自我引导放松法的主要实施思路。","examType":"short","nodeIds":["psy-relaxation","psy-relax-imagery","psy-relax-progressive","psy-relax-self","psy-relax-script"],"printedPages":[147,148,149],"answer":["一、三者共同目的都是减少不必要的身体与心理紧张，为动作完成和适宜心理状态创造条件，但实现途径不同。","二、想象放松法以舒适情境为媒介。利用与个人放松经验有稳定联系的场景，调动多种感觉并配合呼吸，以唤起安全、舒适和放松体验。","三、逐渐放松法以肌肉紧张和放松的感觉对比为基础。先体会局部肌肉紧张，再解除紧张，逐步扩展到全身；熟练后合并肌群、缩短所需时间。","四、自我引导放松法是逐渐放松的简化形式。以呼吸配合自我引导语或想象，按一定程序使各肌群放松；随着熟练，提示语和练习时间逐渐减少。","五、实际运用可根据需要组合，如将舒适情境想象与自我引导结合。选择时应明确训练目的，而不是只背方法名称或把放松等同于失去警觉。"],"keywords":["共同目的","舒适情境","先紧后松","自我引导","可以结合"],"explanation":"统一按“依据什么—怎样进行—怎样发展”对照三个方法，末尾说明相互联系。","sourceType":"original-simulation","highlights":["共同目的","舒适情境","自我引导","动作完成","想象放松","逐渐放松","自我引导放松","感觉对比","简化形式","呼吸","自我引导语","各肌群"]},{"id":"psy-q-attention-difference","prompt":"简述注意的指向性与注意集中的区别，并说明如何避免“越想集中越分心”。","examType":"short","nodeIds":["psy-attention","psy-attention-direction","psy-attention-concentration","psy-attention-con-readiness","psy-attention-con-routine","psy-attention-con-trigger","psy-attention-con-practice","psy-attention-con-alertness"],"printedPages":[149,150,151],"answer":["一、注意的指向性解决选择对象的问题，即从众多刺激中选取任务相关线索并过滤干扰；注意集中解决维持的问题，即在一定时间内保持对已选对象的关注，不能只理解为缩小范围。","二、过度命令自己“必须集中”，可能使注意转向集中本身，并伴随肌肉紧张和心理压力，反而挤占执行当前动作所需的注意。应把关注点回到此时此刻的具体任务。","三、为集中创造条件。降低紧张应激，保持适宜警觉和心理能量；运用临赛前程序减少不确定性，以简明词语或动作触发器提示重新回到任务。","四、按项目要求训练。把注意维持练习纳入训练课，使任务和持续时间接近实际比赛要求，同时提高线索选择与注意转换能力。"],"keywords":["选择对象","维持时间","当前任务","降低应激","程序","触发器","项目练习"],"explanation":"先分清两个概念，再解释反效果，最后给出对应训练路径。","sourceType":"original-simulation","highlights":["选择对象","程序","触发器","指向","集中","过滤干扰","维持","持续时间","项目要求","临赛前程序","动作触发器","词语或动作","比赛要求","心理能量","选择","转换"]},{"id":"psy-q-attention-selection","prompt":"简述训练中帮助运动员将注意指向适宜线索的主要做法。","examType":"short","nodeIds":["psy-attention-direction","psy-attention-dir-analysis","psy-attention-dir-sequence","psy-attention-dir-present","psy-attention-dir-task","psy-attention-dir-filter","psy-attention-dir-prediction","psy-attention-dir-learning","psy-attention-dir-timing","psy-attention-dir-distraction","psy-attention-dir-uncertainty"],"printedPages":[149,150],"answer":["一、依据专项任务确定线索。与运动员分析每种技能需要内部还是外部注意、适宜广度和线索次序，使外部线索精简明确，内部思维积极而有建设性。","二、把注意落在当前行动。关注正在完成及马上完成的动作，关注动作结构和实施，减少对过去失误、得分和未定结果的纠缠。","三、建立选择与预判规则。明确哪些线索应注意、哪些应过滤，训练适宜反应；同时识别有预测价值的线索，判断何时应作出预测反应。","四、结合学习阶段安排。技能学习时重视与动作有关的身体感觉，必要时用想象辅助；初学先减少分心因素，随后逐步引入模拟比赛干扰。","五、安排适宜时机并控制应激。把高注意要求的教学放在精力充足时，重视不确定性和自我价值威胁造成的紧张分心，帮助运动员恢复对任务的关注。"],"keywords":["任务分析","内外广狭","当前行动","选择预判","学习阶段","教学时机","控制应激"],"explanation":"将原书十条按功能归为五点便于背诵，但覆盖范围仍包含十条；展开知识树可逐项核对来源。","sourceType":"original-simulation","highlights":["当前行动","学习阶段","控制应激","次序","精简明确","当前","适宜反应","技能学习","想象辅助","精力充足","不确定性","自我价值威胁","分心"]},{"id":"psy-q-will","prompt":"简述意志品质训练的主要要求，说明它为什么不等于单纯“硬撑”。","examType":"short","nodeIds":["psy-will-training","psy-will-small","psy-will-desire","psy-will-positive","psy-will-competition","psy-will-attention","psy-will-load","psy-will-goal"],"printedPages":[151,152],"answer":["一、从日常小问题开始，培养主动解决问题的愿望。意志不是只在重大比赛中要求拼搏，而是通过日常任务形成认真、主动的应对习惯。","二、运用积极思维建立克服困难的勇气，把训练当作比赛认真投入，避免拖延敷衍；将注意集中于当前任务，使努力落实到具体行动。","三、合理安排心理负荷。毅力练习应提高较长时间承受心理负荷的能力，但不需要过于频繁，不能把无限增加困难当作训练质量。","四、每项练习须有明确目标。既不怕失败，也争取实现目标，使意志努力指向有意义的任务与进步。","五、因此，意志训练是动机、思维、注意、任务和负荷的共同安排。没有目标、忽视频率而一味硬撑，并不符合系统培养意志品质的要求。"],"keywords":["小问题","主动渴望","积极思维","认真投入","当前任务","合理频率","明确目标"],"explanation":"先写可操作要求，再用“有目标、有负荷安排”的条件解释与盲目坚持的区别。","sourceType":"original-simulation","highlights":["小问题","积极思维","认真投入","当前任务","明确目标","克服困难","解决问题","勇气","注意集中","较长时间","心理负荷","不怕失败"]},{"id":"psy-q-requirements","prompt":"简述运动员心理训练的基本要求。","examType":"short","nodeIds":["psy-requirements","psy-require-practice","psy-require-conscious","psy-require-systematic","psy-require-integrate"],"printedPages":[152,153,154],"answer":["一、由感性认识上升到理性认识并付诸实践。不仅承认心理因素重要，还要学习原理与方法，在训练中实际安排；青少年和初级阶段同样应打好心理训练基础。","二、由自发使用转为自觉运用。在教练员持续组织下，把临时救急、凭经验使用，转为有意识、有计划的日常心理技能训练；专家协助不能代替日常实施。","三、由个别零散转为系统运用。全面理解训练内容，持续安排相应方法，不把心理训练缩减为少数技巧，不机械按重要性比例切分时间，也不期待几次练习立刻见效。","四、持之以恒、融会贯通、全面发展。心理技能需要长期培养，并应与体能、技术、战术训练有机结合，共同促进竞技能力发展。"],"keywords":["认识到实践","自发到自觉","零散到系统","长期贯通","全面发展"],"explanation":"沿“认识—实施—组织—持续与结合”四层展开，每层都有针对的常见误区。","sourceType":"original-simulation","highlights":["全面发展","付诸实践","自觉运用","系统运用","持之以恒","融会贯通","理性认识","实际安排","有意识","有计划","全面理解","有机结合"]},{"id":"psy-q-integrated-case","prompt":"某教练认为青少年只需练技术，心理训练等成年后临赛请专家做一次放松即可。请结合心理训练的内容与基本要求评析。","examType":"essay","nodeIds":["psy-training","psy-basic","psy-daily","psy-competition","psy-relaxation","psy-requirements","psy-require-practice","psy-require-conscious","psy-require-systematic","psy-require-integrate"],"printedPages":[142,143,147,148,149,152,153,154],"answer":["一、这种做法把心理训练的对象、内容、时机和实施方式都缩窄了。心理能力是竞技能力的重要组成部分，应从早期训练打基础，不能等到成年或重大比赛失常才补救。","二、内容不止放松。基础心理训练还包括目标设置、想象、注意等技能，专项心理素质，以及动机、自信和意志等个性品质；放松只是其中一种方法，不能代替整个体系。","三、日常与赛期应衔接。青少年基础阶段侧重一般心理特征，随专项任务发展增加专项内容；比赛期还需赛前准备、赛中控制、赛后调整，临赛一次放松不能完成这些任务。","四、训练须自觉、系统、长期开展。教练员应学习原理方法，把心理训练纳入日常计划；专家可以提供专业协助，但持续实施仍需要教练员与运动员共同投入。","五、心理训练要与技术、战术、体能结合。例如技术学习时练习适宜注意线索，日常训练中设置具体表现目标，模拟比赛时练习状态调节，赛后复盘再调整训练。这样才能逐步形成可在比赛中调用的心理能力。"],"keywords":["早期基础","不止放松","日常/赛期衔接","教练员落实","长期系统","与其他训练结合"],"explanation":"按题干四个误区逐一回应，再给可落地的训练结合例子，避免只罗列四条要求而没有评析。","sourceType":"original-simulation","highlights":["不止放松","专项心理素质","个性品质","赛前准备","赛中控制","赛后调整","青少年基础","日常训练","日常计划"]},{"id":"psy-q-attention-case","prompt":"运动员初学动作时能完成，一到模拟比赛便反复想着上一次失误和最终名次，越提醒自己集中越紧张。请提出心理训练思路。","examType":"essay","nodeIds":["psy-goals","psy-goal-performance","psy-goal-specific","psy-imagery","psy-relaxation","psy-attention-dir-present","psy-attention-dir-task","psy-attention-dir-distraction","psy-attention-dir-uncertainty","psy-attention-concentration","psy-attention-con-routine","psy-attention-con-trigger","psy-attention-con-practice"],"printedPages":[143,144,145,146,147,148,149,150,151],"answer":["一、先分析失常的心理环节。其注意停留于过去失误和结果，同时受模拟比赛干扰与紧张影响；过度提醒集中又可能使关注点转向“是否集中”，形成无益紧张。不能简单归为技术不会或意志不足。","二、重建可执行的表现目标。把注意由名次转向当前动作的具体要求，明确本次练习可控制、可核对的任务，用表现反馈替代只按结果评价。","三、训练线索选择与回到当前。确定关键动作线索及次序，过滤无关刺激；用简明提示词或动作触发器，使运动员从上次失误回到正在做和马上要做的动作。","四、降低无益紧张与不确定性。练习适当放松技能，建立稳定而灵活的临赛前程序；保持清醒和警觉，不把放松理解为松散。可用可控制的运动想象演练关键动作与竞赛情境。","五、循序加入干扰并练习维持。先在干扰较少的条件巩固技能，再逐步增加模拟竞赛因素；按实际任务与持续时间练注意集中，并根据训练反馈调整。"],"keywords":["过去/结果占注意","表现目标","当前线索","程序与触发器","放松","逐步干扰","任务时长"],"explanation":"先找题干表现对应的知识节点，再按“目标—线索—状态—情境练习”串成方案；每种方法都说明针对的问题。","sourceType":"original-simulation","highlights":["表现目标","放松","降低无益紧张","当前","不确定性","维持","持续时间","临赛前程序","动作触发器"]},{"id":"know-q-definition","prompt":"名词解释：运动员知识能力。","examType":"term","nodeIds":["know-meaning"],"printedPages":[154],"answer":["运动员知识能力是运动员竞技能力的重要组成部分。它是指运动员掌握和运用运动知识提高竞技运动水平的能力。"],"keywords":["掌握和运用","运动知识","提高竞技运动水平"],"explanation":"名词解释直接记定义原文。检查“掌握”“运用”“目的”三个要素，不要只回答运动员懂多少知识。","sourceType":"original-simulation","definitionVerbatim":true,"highlights":["掌握和运用","运动知识","提高竞技运动水平","掌握","运用"]},{"id":"know-q-understand","prompt":"简述理解运动员知识能力的三个角度，并说明掌握与运用知识的关系。","examType":"short","nodeIds":["know-meaning","know-meaning-nature","know-meaning-access","know-meaning-use"],"printedPages":[154],"answer":["（1）从知识本身看，运动知识是实践中获得的、与运动相关的认识和经验，既有感性成分，也有理性成分；其内容应有助于提高体能、技战术、心理能力和比赛成绩。","（2）从获得途径看，运动知识既来自训练与比赛实践，也来自书本及教练员等他人的传授。与肌肉活动相联系的操作部分，必须在运动实践中形成。","（3）从作用方式看，知识只有被合理运用，才能转化为提高竞技能力和比赛表现的现实作用。掌握是运用的前提，运用并提高竞技运动水平是掌握的目的，因此知识能力同时包含学到与用好两个方面。"],"keywords":["知识本身","获得途径","作用方式","前提与目的"],"explanation":"先依原有三个角度展开，再用“掌握是前提、运用是目的”收束，避免只罗列获得渠道。","sourceType":"original-simulation","highlights":["知识本身","获得途径","作用方式","掌握","运用","提高竞技运动水平","认识和经验","感性","理性","运动实践","操作部分","合理运用","竞技能力","比赛成绩"]},{"id":"know-q-composition","prompt":"试述运动员知识能力的重要作用及其构成。","examType":"essay","nodeIds":["know-meaning","know-meaning-use","know-composition","know-bio","know-psy-education","know-humanities","know-other-science"],"printedPages":[154,155,156],"answer":["（1）运动员知识能力是掌握和运用运动知识提高竞技运动水平的能力。它支持运动员认识训练规律、理解训练要求、分析自身表现，把学习所得转化为体能、技战术和心理能力的改进，并服务于比赛成绩。","（2）其构成应形成与优异成绩相关、合理优化的知识体系。知识结构不仅指知识种类，也包括各种知识的框架及比重；既需要精深的专项知识，也需要广博的一般知识，不能以知识数量代替结构质量。","（3）运动人体生物科学揭示形态、机能与运动素质变化的规律，为负荷安排、监控和恢复提供依据；运动心理学与体育教育学帮助理解技能学习、动机、情绪和行为调节；体育人文社会学科帮助理解价值观、人际关系及团队行为；材料学、气象学、计算机技术等支持器械、环境和信息处理问题。","（4）各类知识的价值在于综合应用。应根据项目特点和个人发展需要，贯穿状态诊断、目标建立、计划制订、组织实施、检查评定和反馈调控，做到既懂专项又能借助相关科学解决训练问题。"],"keywords":["掌握运用","优化结构","专门与一般","四类学科","训练全过程"],"explanation":"这是“作用＋构成”的双任务题。先说明作用，再用知识结构总领各学科，最后联系运用；不要把学科名称当作整份答案。","sourceType":"textbook-review","promptPages":[165],"highlights":["掌握","运用","提高竞技运动水平","比赛成绩","一般知识","运动素质","技能学习","教育","价值观","人际关系","材料学","气象学","计算机技术"]},{"id":"know-q-four-levels","prompt":"运动知识可从解决问题的哪四个层面理解？为什么高水平运动员不能只拥有技能和诀窍？","examType":"short","nodeIds":["know-four-levels","know-facts","know-theory","know-knowhow","know-whoknows"],"printedPages":[156,157],"answer":["（1）事实知识回答“是什么”，科学原理和规律方面的理论知识解释“为什么”，技能和诀窍指导“怎么做”，关于谁掌握某种信息的知识帮助明确相应信息来源。分类依据是知识解决的问题。","（2）技能和诀窍直接服务于动作、战术及心理调适，是竞技实践的重要基础；但只会操作而不了解事实、原理和相关信息，难以深入分析成败原因和适应变化。","（3）四个层面应相辅相成。运动员既应练好动作，又应理解其规律及与其他能力的联系，并获取必要的信息支持，才能更好地改进训练、保持优异成绩及延长运动寿命。"],"keywords":["是什么","为什么","怎么做","谁知道","相辅相成"],"explanation":"先列分类依据和四类，再解释“第三类重要但不够”。各类不要与学科分类或显隐分类混写。","sourceType":"original-simulation","highlights":["是什么","为什么","怎么做","相辅相成","事实","原理","规律","技能","诀窍","信息来源"]},{"id":"know-q-procedural-declarative","prompt":"简述程序性运动知识与陈述性运动知识的区别，并以同一技术动作为例说明。","examType":"short","nodeIds":["know-procedural-declarative","know-procedural","know-declarative","know-serve-example"],"printedPages":[157,158],"answer":["（1）分类依据是动态与静态。程序性运动知识以动态操作形式存在，主要通过动作表达；陈述性运动知识以静态概念形式存在，主要通过语言、文字和符号描述事物特点及相互关系。","（2）程序性知识涉及动作的步骤和过程，体现为“做什么、如何做”的实际完成能力；陈述性知识帮助回答“是什么、为什么、怎么样”，使运动员能够界定动作、分析特点、解释原理并辨别关系。","（3）以排球正面下手发球为例，运动员实际连贯完成准备、抛球和击球，表现出程序性知识；用语言说明动作概念、操作方法、技术分析和要领，则表现出陈述性知识。同一动作可以同时具有这两方面的知识。","（4）学习中应将说明与操作结合。语言理解为练习提供方向，观摩和反复练习使认识转化为稳定动作；能够说出要领，并不必然等于能够熟练完成动作。"],"keywords":["动态与静态","动作表达","语言描述","同一动作","说明与操作结合"],"explanation":"用“标准—表达—任务—例子—联系”比较同一对象。不要把两类写成互不相干的知识。","sourceType":"original-simulation","highlights":["动态与静态","动作表达","同一动作","说明与操作结合","动态操作","静态概念","动作","语言","步骤和过程","概念","原理","方法","技术分析"]},{"id":"know-q-skill-acquisition","prompt":"运动员怎样通过学习逐步形成程序性运动知识？","examType":"short","nodeIds":["know-procedural","know-procedural-acquire","know-demonstration","know-verbal","know-abilities-practice"],"printedPages":[157,160,163],"answer":["（1）明确要掌握的动作与任务，通过观察教练员或他人的示范建立视觉表象，认识动作顺序和基本形态。必要的语言提示帮助抓住关键环节，但不能代替动作实践。","（2）在反复练习中建立、巩固动觉表象，逐渐掌握身体位置、力量、幅度、方向、速度及动作衔接，对照指导和实际效果调整动作。","（3）长期积累使操作逐步连贯和稳定，并可达到动作自动化。由于经验具有个体性，运动员需要在具体任务和情境中亲自练习，形成属于自己的技能、经验和诀窍。"],"keywords":["视觉表象","动觉表象","反复练习","自动化","个体经验"],"explanation":"按形成过程回答，先观察后练习再稳定；不要只列动作技术的几个组成环节。","sourceType":"original-simulation","highlights":["视觉表象","动觉表象","反复练习","自动化","观察","练习","长期积累"]},{"id":"know-q-tacit-explicit","prompt":"简述显性运动知识与隐性运动知识的区别及联系。","examType":"short","nodeIds":["know-explicit-tacit","know-tacit","know-explicit","know-conversion"],"printedPages":[158,159],"answer":["（1）分类标准是能否清晰地表述和有效地转移。显性运动知识可以通过语言、文字、图示或数学公式等表达；隐性运动知识更多体现为难以完整言传的实践经验。","（2）显性知识便于记录、解释和交流，隐性知识则与具体情境、个人经验紧密联系。例如能描述动作要领是显性表达，而比赛中对来球作出及时、准确处理所依赖的经验，可能仍难以完整说明。","（3）二者共同构成运动员的知识，不能以是否说得清作为有无知识的唯一标准。隐性知识也包括认知方面的直觉、价值观和团队默契，并非只有技术动作。","（4）在一定条件下，运动员可通过比较、分析、总结与交流，把部分隐性经验转为显性知识；又可把学到的显性知识用于练习，逐渐形成新的个人实践经验。"],"keywords":["表述与转移","实践经验","情境与个体","双向联系"],"explanation":"先按同一标准比较，再回答关系和转化。最后一点的反向运用来自本节后续训练与应用内容。","sourceType":"original-simulation","highlights":["实践经验","显性","隐性","语言","数学公式","一定条件"]},{"id":"know-q-classification-cross","prompt":"为什么不能把“程序性知识”和“隐性知识”完全当作同一概念？请联系运动学习说明。","examType":"short","nodeIds":["know-procedural-declarative","know-procedural","know-declarative","know-explicit-tacit","know-tacit","know-explicit","know-study-methods"],"printedPages":[157,158,159,162],"answer":["（1）两套分类依据不同。程序性与陈述性看知识是动态操作还是静态概念形式；显性与隐性看知识能否清晰表述和有效转移。相关内容可能重合，但不能因重合就取消标准差别。","（2）运动技能的操作部分常具有难以言传的特点，因此程序性知识与隐性经验联系密切；但隐性知识还包括洞察力、价值观、心智模式及团队默契，范围不只限于动作步骤。","（3）对同一个技术动作，实际完成体现操作能力，文字说明其方法和原理体现陈述与显性表达。把动作经验总结为可讲清的要领，是表达方式的转化，不意味着已经摆脱实践练习。","（4）学习时应分别判断“这是什么形式的知识”和“能否清楚表达”。既练动作，又学会解释与反思，才能避免只背文字或只凭感觉两种偏向。"],"keywords":["分类标准不同","相关但不等同","认知隐性知识","操作与表达"],"explanation":"这是易混概念辨析题。先指出不同标准，再用重合处与不重合处证明，避免做简单一一对应。","sourceType":"original-simulation","highlights":["动态操作","静态概念","动作","概念","原理","清晰表述","有效转移","显性","隐性","难以言传"]},{"id":"know-q-team-guidance","prompt":"简述运动员从训练团队获得知识能力的主要方式及其作用。","examType":"short","nodeIds":["know-team","know-demonstration","know-verbal","know-research-team"],"printedPages":[160],"answer":["（1）教练员的动作示范把难以纯靠语言描述的操作展现出来。运动员通过观察、模仿和练习学习动作，分享并运用教练员所展现的隐性知识。","（2）教练员的语言提示说明动作特点、关键要领和环节联系，还可以解释相关生物力学、生理和心理机制。运动员通过聆听、分析和实践，将这些显性表达落实到自己的动作中。","（3）教练团队的科研人员通过监测、研究和专业服务，提供关于专项训练、恢复、营养、体重控制和心理调控等知识。结合个体特点解释信息，有助于运动员认识自身状态并改进训练。","（4）三种方式应相互补充：示范帮助把握动作，语言帮助理解关键，科研帮助获得针对性认识，最终都要由运动员在实践中消化和运用。"],"keywords":["动作示范","语言提示","科研人员","观察模仿","实践消化"],"explanation":"按教材三个下级标题逐项回答，每点写“谁提供什么—运动员怎样学—有什么作用”。","sourceType":"original-simulation","highlights":["动作示范","语言提示","科研人员","示范","观察","模仿","练习","隐性知识","环节联系","专业服务"]},{"id":"know-q-school-learning","prompt":"为什么运动员知识能力的发展不能忽视文化学习和学校教育？","examType":"short","nodeIds":["know-life-study","know-life","know-school","know-multidisciplinary"],"printedPages":[160,161,163],"answer":["（1）学校教育具有目的性、计划性和系统性，能够帮助运动员较有效地掌握知识技能，并形成相应观点、信念与行为习惯。它与生活环境中零散获得信息的方式各有作用。","（2）文化学习发展认识工具。语文学习提高表达、观察和概括能力，便于总结与交流运动经验；数学学习发展逻辑思维、分析与推理能力，便于寻找训练成败原因。","（3）自然科学基础帮助理解速度、力、运动轨迹和人体机能等运动现象；体育专业及相关学科学习进一步提供专项知识和一般基础原理，支持理解训练要求和提高竞技能力。","（4）知识能力最终要服务于实践。文化与理论学习应结合个人训练中的问题，经过分析和应用发挥作用，不能把提高文化水平与专项发展相互割裂。"],"keywords":["系统性","表达概括","逻辑推理","科学基础","联系专项"],"explanation":"分清“增加知识”和“发展思维工具”两个作用，再落到训练实践，答案就不只是在说学习重要。","sourceType":"original-simulation","highlights":["系统性","科学基础","生活环境","学校教育","相关学科"]},{"id":"know-q-process-experience","prompt":"结合所学专项，试说明隐性运动知识向显性运动知识的转化。","examType":"essay","nodeIds":["know-tacit","know-explicit","know-conversion","know-practice-tacit","know-process-tacit","know-reflection"],"printedPages":[158,159,162,163,164],"answer":["（1）隐性运动知识常体现为在特定情境中形成、本人能够运用却难以完整表达的经验；向显性知识转化，是把其中可以认识和提炼的内容转为他人较易理解的描述，并非把所有感觉一次完全说清。","（2）以乒乓球击球为例，运动员起初能够依据来球凭经验调整并完成击球，但未必能清楚解释步法、重心和出手之间的关系。首先应通过反复练习、观察记录和结果比较，积累成功与失败的具体材料。","（3）再分析动作差异和发生条件，比较重心位置、步法调整与击球效果，逐渐归纳各要素之间的联系，用准确的概念和语言提炼为动作要领或判断依据，完成由“会做但难说”到“能够解释”的进展。","（4）教练员引导提问和讲评，运动员自我反思，队友交流讨论，都有助于把内隐认识表达出来。提炼出的结论还应回到后续训练中检验和修正，明确适用条件，避免把一次成功误当作普遍规律。"],"keywords":["具体经验","成功失败比较","分析归纳","语言提炼","交流反思","再检验"],"explanation":"先界定转化，再以一个专项贯穿全过程。例子写清“原来不会说什么—怎么分析—后来能说清什么”，而非只写会做变会说。","sourceType":"textbook-review","promptPages":[165],"highlights":["语言提炼","语言","特定情境","反复练习","自我反思","交流"]},{"id":"know-q-professional-theory","prompt":"简述运动员学习体育专业理论知识的方法与特殊要求。","examType":"short","nodeIds":["know-professional-study","know-study-methods","know-combine-training","know-multidisciplinary","know-abilities-practice"],"printedPages":[162,163],"answer":["（1）采用阅读自学、教师讲解辅导、小组讨论、完成作业和专题研究等一般方法，并根据运动员文化水平、学习任务及条件选择合适形式。","（2）特殊要求是紧密结合训练实践，尤其是自己的训练，以解决实际问题并取得效果。应认真理解训练计划、记好训练日记、进行训练总结，带着问题学习、思考与验证。","（3）既观察分析本人，也科学比较同伴、对手及优秀运动员的实践，发现训练成功的规律；把理论概念与自身经验结合，避免只背理论而不能运用。","（4）除本专项理论外，要广泛学习相关科学知识；体能、技战术和心理能力的实践部分，则须通过长期训练与比赛积累形成，理论讲解不能替代本人操作。"],"keywords":["一般方法","特殊要求","计划日记总结","观察比较","多学科","长期实践"],"explanation":"先答一般方法，再突出“结合自己的实践”这一特殊要求，最后补广度和实践部分。","sourceType":"original-simulation","highlights":["一般方法","特殊要求","阅读自学","讲解辅导","小组讨论","训练计划","训练日记","训练总结","专项理论","实践部分"]},{"id":"know-q-two-paths","prompt":"简述提高应用理论知识自觉性的两条路径，并说明如何避免被动学习。","examType":"short","nodeIds":["know-conscious","know-practice-to-theory","know-theory-to-practice"],"printedPages":[163],"answer":["（1）先明确专业理论知识在训练中的作用，主动寻找可应用的环节，是提高应用水平的前提。其路径之一是由实践到理论：根据训练中的问题学习相关理论，理解后用于实践，特点是目的明确、针对性强。","（2）另一条路径是先理论、后实践：在系统学习中发现能够改进训练的新认识，再主动调整训练或比赛准备。例如从美学知识中获得动作编排思路，再在项目实践中检验效果。","（3）两条路径的出发点不同，但都要落在应用与检验。教练员可增加“提问—讨论—讲评”，使运动员主动观察、解释和评价自己的行为，逐步提高分析判断能力，避免只接受口令而不理解。"],"keywords":["实践到理论","理论到实践","应用检验","提问讨论讲评"],"explanation":"按起点区分两条路径，再写共同落点。不要把它们写成互斥的训练阶段。","sourceType":"original-simulation","highlights":["实践到理论","针对性"]},{"id":"know-q-pre-post","prompt":"如何通过赛前分析、赛后总结及交流反思提高运动员知识能力？","examType":"short","nodeIds":["know-reflection","know-process-tacit","know-own-experience"],"printedPages":[162,163,164],"answer":["（1）赛前组织集体分析，明确自己与对手的竞技能力特征、技战术要求和可能情境，使已有知识服务于比赛准备。","（2）赛后及时回顾关键表现和比赛成败原因，对照具体任务与条件分析行为及效果。通过总结揭示事物间的联系，使理论认识更深、实践解析更准。","（3）总结既是将隐性经验显性化的语言过程，也是自我反思过程。运动员要提炼并表达经验，教练员帮助追问和辨析，队友相互交流，使个人的内隐观点得到理解和检验。","（4）将总结形成的认识用于后续训练和比赛，并继续观察结果。这样才能从一次结果的回顾走向知识积累，避免只记录输赢或提出空泛决心。"],"keywords":["赛前特征分析","赛后成败原因","表达反思","教练队友交流","后续应用"],"explanation":"按赛前、赛后、反思交流、再次应用串起过程；本题不要求罗列心理训练方法。","sourceType":"original-simulation","highlights":["自我反思","交流","回顾"]},{"id":"know-q-ways","prompt":"结合现实，谈谈提高运动员知识能力的途径有哪些。","examType":"essay","nodeIds":["know-meaning","know-team","know-life-study","know-practice","know-professional-study","know-conscious","know-reflection","know-practice-application"],"printedPages":[154,159,160,161,162,163,164],"answer":["（1）提高知识能力应同时发展知识的掌握与运用，并兼顾显性知识和隐性经验。先根据专项要求、运动员知识基础及现实训练问题，识别需要补充的知识，避免只追求学习数量。","（2）从训练团队获得指导。通过观察、模仿和练习学习教练员示范，通过聆听、分析理解动作提示与原理，并利用科研人员提供的个体监测和专业服务，形成对训练问题的针对性认识。","（3）通过生活、学校教育和书本学习拓宽知识。主动选择有价值的信息，发展表达、概括、逻辑推理和分析能力；在专项理论之外学习相关学科，优化专门知识与一般知识的结构。","（4）在运动实践中积累并加工经验。把练习形成的感觉和操作，通过成功失败比较、训练日记、教练讲评及队友交流逐步提炼，促进隐性经验向显性认识转化；再将理论与个人经验结合，形成新的操作能力。","（5）把知识用于现实问题。主动开展赛前分析与赛后总结，运用自身经验、他人成功经验及科研成果，在后续训练中检查效果并调整。形成学习—实践—反思—再学习的循环，才会使知识增长转化为竞技水平的提高。"],"keywords":["掌握与运用","训练团队","生活学校","实践加工","专业学习","循环提高"],"explanation":"跨越“获得与提高”和“运用”两个大分支。用一个真实训练问题串联渠道、方法和检验，作答会更完整。","sourceType":"textbook-review","promptPages":[165],"highlights":["掌握与运用","训练团队","掌握","运用","示范","学校教育","赛前分析","赛后总结","交流","自身经验","科研成果"]},{"id":"know-q-case-synthesis","prompt":"某运动员能完成技术动作，却说不清成功原因；看过理论后仍不会用，还常把一次比赛失误归结为“感觉不好”。请运用本节知识提出改进方案。","examType":"essay","nodeIds":["know-meaning","know-procedural","know-declarative","know-tacit","know-explicit","know-process-tacit","know-combine-training","know-conscious","know-reflection","know-practice-application"],"printedPages":[154,157,158,159,162,163,164],"answer":["（1）先作知识诊断。能够完成动作说明已有一定程序性知识和隐性经验；说不清成功原因、理论不能用于训练，提示陈述性理解、经验提炼及知识运用存在不足。不能据此认定其“没有知识”，也不能把知识能力等同于动作熟练程度。","（2）围绕专项任务收集材料。结合训练计划和日记记录成功、失败情境，比较动作与结果；由教练员示范并提示关键，帮助运动员观察和分析自己，逐渐形成对动作概念、特点及环节关系的明确认识。","（3）引导经验显性化。采用提问、讨论、讲评及赛后总结，让运动员具体说明当时的判断、动作、条件和后果；对“感觉不好”继续追问，通过比较归纳可解释的经验，避免仅用笼统感受代替分析。","（4）把理论转成可实施的调整。根据实践问题选择相关理论，与本人经验结合，设计适合当前水平的练习；必要时借助科研团队的专业信息。既要理解语言说明，也要通过反复练习形成新的操作经验。","（5）用后续表现检验方案。赛前分析预期情境，赛后检查调整是否有效，明确结论的适用条件，并再次修正。通过学习、运用与反思的持续循环，把“会做”逐步发展为“理解并能改进自己的做法”。"],"keywords":["诊断知识结构","成功失败比较","隐性显性化","理论联系实际","后续检验"],"explanation":"这是原创综合题。按诊断—取证—提炼—应用—检验组织，不要把所有小标题机械抄一遍；每个措施都要回应题干中的具体困难。","sourceType":"original-simulation","highlights":["运用","概念","语言","反复练习","训练计划","赛前分析","赛后总结"]}],"comparisons":[{"id":"psy-c-classification","title":"两套心理训练分类：分类标准不同，不能一一对应","nodeIds":["psy-content-class","psy-basic","psy-targeted","psy-period-class","psy-competition","psy-daily"],"printedPages":[142,143],"columns":["分类依据","类别","主要任务与边界"],"rows":[["训练内容与针对性","基础的心理训练（一般心理训练）","建立基本心理素质：心理技能、专项心理素质、个性品质。"],["训练内容与针对性","有针对性的心理训练（专门心理训练）","围绕具体比赛准备或特定心理问题。"],["与训练和比赛的关系","日常心理训练（训练期心理训练）","相对偏重技能发展和个性心理特征改善。"],["与训练和比赛的关系","比赛期心理训练","侧重特定比赛心理过程：赛前、赛中、赛后。"]],"note":"同一次训练可同时具有“日常阶段”和“有针对性”等属性。“一般”训练中也有专项心理素质；不要凭字面把一般等同无专项内容。"},{"id":"psy-c-competition","title":"赛前、赛中、赛后：同一赛期中的不同任务","nodeIds":["psy-before","psy-during","psy-after"],"printedPages":[142],"columns":["分类依据","类别","任务与易漏点"],"rows":[["比赛时间阶段","赛前准备","动机、适宜激活、信心、思维与行为程序。"],["比赛时间阶段","赛中控制","随情境变化稳定情绪，保证能力发挥。"],["比赛时间阶段","赛后调整","成功者防自满并反思，失败者缓解消极体验并恢复求胜动机。"]],"note":"赛期不等于赛前；赛后也不是只安慰失败者，成功者同样需要调节。"},{"id":"psy-c-goal-axes","title":"六组目标考量：可以同时作用于同一个目标","nodeIds":["psy-goals","psy-goal-performance","psy-goal-challenge","psy-goal-realistic","psy-goal-specific","psy-goal-time","psy-goal-individual"],"printedPages":[143,144,145],"columns":["考量维度","对照类别","区分与采用原则"],"rows":[["控制内容","表现目标／结果目标","表现由自身控制为主；结果还受对手等影响，重点落到可控表现。"],["难度","挑战性／轻而易举","需要激发努力，又不因过难削弱动机。"],["实际依据","现实／非现实","以真实能力与进程为基础，必要时调整。"],["明确程度","具体／笼统","有成功标准、数量化要求及特定时间或事件。"],["时间跨度","短期／长期","近期执行与反馈支撑远期方向，远期降低单次比赛的过重负担。"],["责任主体","个体／全队","个人责任清晰，支撑团队合作并预防冲突。"]],"note":"这不是六类互斥目标。一个个体短期目标仍须同时具体、现实、有挑战，并尽量指向可控表现。"},{"id":"psy-c-imagery-layers","title":"想象训练的阶段、条件与评价：三个问题不要混答","nodeIds":["psy-imagery-stages","psy-imagery-conditions","psy-imagery-evaluation"],"printedPages":[146,147],"columns":["分类依据","内容","回答的问题"],"rows":[["技能发展顺序","感觉意识→鲜明生动性→控制性","怎样由已有经验发展为可控的内部演练？"],["练习准备条件","背景、注意放松状态、想象提示物","在什么环境与状态下、借助什么开始练？"],["训练质量评价","清晰度、颜色、声音、连贯活动性、肌肉感觉、情绪深度、自主控制","练得是否清楚、完整、可控？"]],"note":"“控制性”既是发展阶段，又可在评价时检查；它们侧重点不同，不能见到相同词就把层级合并。"},{"id":"psy-c-relaxation","title":"三种放松方法：目的相近，实施依据不同","nodeIds":["psy-relax-imagery","psy-relax-progressive","psy-relax-self"],"printedPages":[147,148,149],"columns":["分类依据","方法","核心路径与联系"],"rows":[["达成放松的主要路径","想象放松法","舒适情境与个人放松经验联系→多感觉想象→唤起放松。"],["达成放松的主要路径","逐渐放松法","先感受局部肌肉紧张→解除紧张→由局部到全身→熟练后合并肌群。"],["达成放松的主要路径","自我引导放松法","逐渐放松的简化形式：呼吸＋自我引导语/想象→全身逐渐放松。"]],"note":"想象是可用于多种任务的技能；想象放松是以放松为目的的一种使用。简化脚本不是第四种并列放松法。"},{"id":"psy-c-attention","title":"注意指向与注意集中：选择什么、维持多久","nodeIds":["psy-attention-direction","psy-attention-concentration"],"printedPages":[149,150,151],"columns":["比较维度","注意的指向性","注意的集中"],"rows":[["核心问题","从众多刺激中选什么、过滤什么","在需要的时间内能否维持所选对象"],["训练重点","任务分析、内外与广狭、线索次序、预测线索、阶段性抗干扰","减少应激、临赛前程序、触发器、符合比赛要求的持续练习"],["易错理解","所有情境都只看一种固定线索","集中等于范围越窄越好，或越用力命令自己越好"]],"note":"两者相互配合；选错对象却维持很久，同样不能保证动作质量。内部/外部是来源，广阔/狭窄是范围，两条轴也不能混成一条。"},{"id":"psy-c-requirements","title":"四项基本要求：不是四种具体训练方法","nodeIds":["psy-require-practice","psy-require-conscious","psy-require-systematic","psy-require-integrate"],"printedPages":[152,153,154],"columns":["解决的层面","要求","主要纠正的误区"],"rows":[["认识与行动","感性认识→理性认识并付诸实践","只承认重要却不安排；青少年无需训练。"],["实施主动性","自发使用→自觉运用","出问题才做、临赛救急、完全依赖专家。"],["组织完整性","个别零散→系统运用","只会一两种技巧、机械按重要性比例分时、几次就求奇效。"],["持续性与整合","持之以恒、融会贯通、全面发展","把心理与体能、技术、战术割裂，缺少长期投入。"]],"note":"目标设置、想象、放松等是“用什么练”；四项要求回答“怎样把训练真正组织和落实”。"},{"id":"know-c-standards","title":"三套知识分类先辨依据，再记类别","nodeIds":["know-composition","know-classification","know-four-levels","know-procedural-declarative","know-explicit-tacit"],"printedPages":[154,156,157,158,159],"columns":["分类依据","类别","判断问题／提醒"],"rows":[["知识解决的问题","事实、原理规律、技能诀窍、谁掌握信息","分别回答是什么、为什么、怎么做、谁知道；四层相辅相成。"],["动态与静态（教育心理学角度）","程序性运动知识、陈述性运动知识","看动态操作与静态概念形式，侧重动作表达与语言描述。"],["能否清晰表述和有效转移","显性运动知识、隐性运动知识","看能否清楚表达与交流；隐性并非仅指技术操作。"],["知识内容结构（另一个观察角度）","专门与一般；相关多学科知识","回答需要掌握哪些知识及其比重，不与上面各套标准混列。"]],"note":"同一知识可以同时从多个维度观察。例如某动作的原理说明可以既回答“为什么”，又具有陈述性和显性特点。不能把不同标准产生的类别强行排成互斥的一行。"},{"id":"know-c-procedural-declarative","title":"程序性与陈述性：同一动作的“做”和“说”","nodeIds":["know-procedural","know-declarative","know-procedural-acquire","know-serve-example"],"printedPages":[157,158],"columns":["比较维度","程序性运动知识","陈述性运动知识"],"rows":[["主要形式","动态操作，主要靠动作表达","静态概念，主要靠语言、文字或符号表达"],["核心任务","实际完成操作步骤和过程","描述特点、说明原理与相互关系"],["同一发球例子","运动员实际完成抛球、摆臂和击球","说出发球概念、方法、技术分析及要领"],["学习侧重","观摩、反复练习、动觉表象与自动化","理解概念、辨析关系、语言说明与原理分析"]],"note":"两类相互支持，不能用“会说”代替“会做”；一段书面的操作说明也不能直接当作本人已经形成的操作能力。"},{"id":"know-c-explicit-tacit","title":"显性与隐性：能否表达，不是有没有知识","nodeIds":["know-tacit","know-explicit","know-conversion"],"printedPages":[158,159],"columns":["比较维度","显性运动知识","隐性运动知识"],"rows":[["表达特点","能借语言、图示、数学公式等较清晰表达","实践中能运用，但难以完整言传"],["具体表现","动作描述、要领、训练与比赛特点的说明","动作经验、诀窍、直觉、价值观、团队默契等"],["传递与获得","可通过说明、书本和交流分享，仍须实践理解","依赖具体情境、个人经历、观察模仿与训练积累"],["相互关系","经实践可融入个人新的操作经验","在一定条件下可经反思、比较和总结转为显性认识"]],"note":"程序性与隐性联系密切但不完全等同。知识分类依据不同；隐性知识还有认知与群体文化等成分。"},{"id":"know-c-guidance","title":"训练团队三种传授方式各补什么","nodeIds":["know-demonstration","know-verbal","know-research-team"],"printedPages":[160],"columns":["方式","提供的知识与途径","运动员怎样消化"],"rows":[["动作示范","以动作展现“怎样做”，分享操作经验","观察—模仿—练习，逐步形成自己的操作能力"],["语言提示","指出特点、要领、环节联系及相关原理","聆听—分析—实践，检验理解是否落实到动作"],["科研人员传授","提供专项研究、个体监控及专业服务信息","理解个人特点与状态，结合训练问题加以运用"]],"note":"三种方式相互补充；不是看过示范、听过讲解或拿到数据，就已经完成知识能力训练。"},{"id":"know-c-directions","title":"两种转化与两条应用路径分别是什么","nodeIds":["know-process-tacit","know-combine-training","know-conscious","know-practice-to-theory","know-theory-to-practice","know-others-experience"],"printedPages":[162,163,164],"columns":["观察维度","方向／类别","例子与区别"],"rows":[["知识表达的转化","隐性经验→显性认识","比较成功失败的击球，归纳并说清步法、重心与击球的联系。"],["知识融入操作","显性认识→新的个人实践经验","把讲清的动作要领用于长期练习，形成稳定、熟练的操作。"],["理论应用的起点","由实践到理论","先发现负荷控制问题，再学习相关理论并应用。"],["理论应用的起点","先理论，后实践","先从理论学习获得新思路，再改进训练并检验效果。"]],"note":"前两行谈经验与表达怎样变化；后两行谈寻找理论应用机会从哪里出发。它们可能发生在同一学习过程中，但不能当作同一个分类。"},{"id":"know-c-acquire-use","title":"“获得与提高”与“运用”如何分清","nodeIds":["know-acquisition","know-professional-study","know-application","know-reflection","know-practice-application"],"printedPages":[159,160,161,162,163,164],"columns":["所在分支","着重回答","相邻概念的联系"],"rows":[["获得与提高","知识从哪里来、怎样学与加工","团队、生活学校、运动实践和专业学习；训练实践既获得经验，也加工经验。"],["运用","学到的知识怎样解决训练与比赛问题","主动应用理论、赛前分析赛后总结、运用自身经验、他人经验及科研成果。"],["共同点","学习、实践、再学习、再实践","总结既能获得更清晰的认识，也能为下一次应用提供依据，两大分支并不截然割裂。"]],"note":"考试若问“主要来源”应先突出获得渠道；若问“如何应用”，应突出解决问题与实践检验，不能两题都只列同一组名称。"}],"bankLinks":[{"bankId":"sp4-training-069","nodeIds":["psy-definition"]},{"bankId":"sp4-training-070","nodeIds":["psy-goals"]},{"bankId":"sp4-training-071","nodeIds":["psy-imagery"]},{"bankId":"sp4-training-072","nodeIds":["psy-relaxation","psy-relax-imagery","psy-relax-progressive","psy-relax-self"]},{"bankId":"sp4-training-073","nodeIds":["psy-attention"]},{"bankId":"sp4-training-074","nodeIds":["psy-will-training"]},{"bankId":"sp4-training-075","nodeIds":["psy-goals","psy-imagery","psy-relaxation","psy-attention"]},{"bankId":"sp4-training-076","nodeIds":["psy-requirements"]},{"bankId":"sp4-training-077","nodeIds":["know-meaning"]},{"bankId":"sp4-training-078","nodeIds":["know-explicit","know-explicit-tacit"]},{"bankId":"sp4-training-079","nodeIds":["know-tacit","know-explicit-tacit"]},{"bankId":"sp4-training-080","nodeIds":["know-team","know-life-study","know-practice","know-professional-study","know-conscious","know-reflection","know-practice-application"]}],"source":{"title":"运动训练学（第二版）","author":"田麦久 主编","publisher":"高等教育出版社","edition":"2017年第二版（所用扫描本2019年重印）","file":"原版 运动训练学 (田麦久第2版) 教材电子版.pdf","printedContent":[141,164],"reviewQuestionPages":[164,165],"verification":"逐页核对用户提供的扫描教材原图；原标题、编号分项与整理辅助节点分开标记。"},"summary":{"nodes":148,"originalItems":118,"organizedPoints":26,"questions":32,"comparisons":13,"bankQuestions":12}};
